BIBLIOTECA.textos({
"luis-de-camoes-soneto-enquanto-quis-fortuna-que-tivesse": {"t":["Enquanto quis fortuna que tivesse\nEsperança de algum contentamento,\nO gosto de um suave pensamento\nMe fez que seus efeitos escrevesse.\n\nPorém temendo Amor que aviso desse\nMinha escritura a algum juízo isento,\nEscureceu-me o engenho co'o tormento,\nPara que seus enganos não dissesse.\n\nÓ vós, que Amor obriga a ser sujeitos\nA diversas vontades! quando lerdes\nN'um breve livro casos tão diversos;\n\n(Verdades puras são, e não defeitos)\nEntendei que segundo o amor tiverdes,\nTereis o entendimento de meus versos."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, I, p. 1.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nPrimeiro soneto da ed. de 1843.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Em_quanto_quiz_fortuna_que_tivesse"}]}},
"luis-de-camoes-soneto-eu-cantarei-de-amor-tao-docemente": {"t":["Eu cantarei de amor tão docemente,\nPor uns termos em si tão concertados,\nQue dous mil acidentes namorados\nFaça sentir ao peito que não sente.\n\nFarei que Amor a todos avivente,\nPintando mil segredos delicados,\nBrandas iras, suspiros magoados,\nTemerosa ousadia, e pena, ausente.\n\nTambém, Senhora, do desprezo honesto\nDe vossa vista branda e rigorosa,\nContentar-me-ei dizendo a menor parte.\n\nPorém para cantar de vosso gesto\nA composição alta e milagrosa,\nAqui falta saber, engenho, e arte."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, II, p. 2.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Eu_cantarei_de_amor_t%C3%A3o_docemente"}]}},
"luis-de-camoes-soneto-com-grandes-esperancas-ja-cantei": {"t":["Com grandes esperanças já cantei,\nCom que os deuses no Olimpo conquistara;\nDepois vim a chorar porque cantara,\nE agora choro já porque chorei.\n\nSe cuido nas passadas que já dei,\nCusta-me esta lembrança só tão cara,\nQue a dor de ver as mágoas que passara,\nTenho por a mor mágoa que passei.\n\nPois logo, se está claro que um tormento\nDá causa que outro na alma se acrescente,\nJá nunca posso ter contentamento.\n\nMas esta fantasia se me mente?\nOh ocioso e cego pensamento!\nAinda eu imagino em ser contente?"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, III, p. 2.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Com_grandes_esperanças_ja_cantei"}]}},
"luis-de-camoes-soneto-despois-que-quis-amor-que-eu-so-passasse": {"t":["Despois que quis Amor que eu só passasse\nQuanto mal já por muitos repartiu,\nEntregou-me à Fortuna, porque viu\nQue não tinha mais mal que em mi mostrasse.\n\nEla, porque do Amor se avantajasse\nNa pena a que ele só me reduziu,\nO que para ninguém se consentiu,\nPara mim consentiu que se inventasse.\n\nEis-me aqui vou com vário som gritando.\nCopioso exemplário para a gente\nQue destes dous tiranos é sujeita;\n\nDesvarios em versos concertando.\nTriste quem seu descanso tanto estreita,\nQue deste tão pequeno está contente!"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, IV, p. 3.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CED)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Despois_que_quiz_Amor_que_eu_só_passasse"}]}},
"luis-de-camoes-soneto-em-prisoes-baixas-fui-um-tempo-atado": {"t":["Em prisões baixas fui um tempo atado;\nVergonhoso castigo de meus erros:\nInda agora arrojando levo os ferros,\nQue a morte, a meu pesar, tem já quebrado.\n\nSacrifiquei a vida a meu cuidado,\nQue Amor não quer cordeiros nem bezerros;\nVi mágoas, vi misérias, vi desterros:\nParece-me que estava assi ordenado.\n\nContentei-me com pouco, conhecendo\nQue era o contentamento vergonhoso,\nSó por ver que cousa era viver ledo.\n\nMas minha Estrela, que eu já agora entendo,\nA Morte cega, e o Caso duvidoso\nMe fizeram de gostos haver medo."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, V, p. 3.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Em_prisões_baixas_fui_hum_tempo_atado"}]}},
"luis-de-camoes-soneto-ilustre-e-digno-ramo-dos-meneses": {"t":["Ilustre e digno ramo dos Meneses,\nAos quais o providente e largo Céu\n(Que errar não sabe) em dote concedeu,\nRompessem os Maométicos arneses;\n\nDesprezando a Fortuna e seus reveses,\nIde para onde o Fado vos moveu;\nErguei flamas no mar alto Eritreu,\nE sereis nova luz aos Portugueses.\n\nOprimi com tão firme e forte peito\nO Pirata insolente, que se espante\nE trema Taprobana e Gedrosia.\n\nDai nova causa à cor do Árabo Estreito;\nAssi que o Roxo mar, daqui em diante\nO seja só com sangue de Turquia."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, VI, p. 4.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\n«Gedrosia» sem acento, como na fonte: a rima com «Turquia» pede a tônica no i (hoje se grafa Gedrósia)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Illustre_e_digno_ramo_dos_Menezes"}]}},
"luis-de-camoes-soneto-no-tempo-que-de-amor-viver-soia": {"t":["No tempo que de amor viver soía,\nNem sempre andava ao remo ferrolhado;\nAntes agora livre, agora atado,\nEm várias flamas variamente ardia.\n\nQue ardesse n'um só fogo não queria\nO Céu porque tivesse exprimentado\nQue nem mudar as causas ao cuidado\nMudança na ventura me faria.\n\nE se algum pouco tempo andava isento,\nFoi como quem co'o peso descansou\nPor tornar a cansar com mais alento.\n\nLouvado seja Amor em meu tormento,\nPois para passatempo seu tomou\nEste meu tão cansado sofrimento!"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, VII, p. 4.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC CDC)\n\n**Notas sobre o texto.**\n\n«sohia» (fonte) = soía, 3 sílabas (so-í-a)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/No_tempo_que_de_amor_viver_sohia"}]}},
"luis-de-camoes-soneto-amor-que-o-gesto-humano-na-alma-escreve": {"t":["Amor, que o gesto humano na alma escreve,\nVivas faíscas me mostrou um dia,\nDonde um puro cristal se derretia\nPor entre vivas rosas e alva neve.\n\nA vista, que em si mesma não se atreve,\nPor se certificar do que ali via,\nFoi convertida em fonte, que fazia\nA dor ao sofrimento doce e leve.\n\nJura Amor, que brandura de vontade\nCausa o primeiro efeito; o pensamento\nEndoudece, se cuida que é verdade.\n\nOlhai como Amor gera, em um momento,\nDe lágrimas de honesta piedade\nLágrimas de imortal contentamento."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, VIII, p. 5.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Amor,_que_o_gesto_humano_na_alma_escreve"}]}},
"luis-de-camoes-soneto-tanto-de-meu-estado-me-acho-incerto": {"t":["Tanto de meu estado me acho incerto,\nQue em vivo ardor tremendo estou de frio;\nSem causa juntamente choro e rio;\nO mundo todo abarco, e nada aperto.\n\nÉ tudo quanto sinto um desconcerto:\nDa alma um fogo me sai, da vista um rio;\nAgora espero, agora desconfio;\nAgora desvario, agora acerto.\n\nEstando em terra, chego ao céu voando;\nN'um'hora acho mil anos, e é de jeito\nQue em mil anos não posso achar um'hora.\n\nSe me pergunta alguém, por que assi ando,\nRespondo, que não sei: porém suspeito\nQue só porque vos vi, minha Senhora."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, IX, p. 5.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Tanto_de_meu_estado_me_acho_incerto"}]}},
"luis-de-camoes-soneto-transforma-se-o-amador-na-cousa-amada": {"t":["Transforma-se o amador na cousa amada,\nPor virtude do muito imaginar:\nNão tenho logo mais que desejar,\nPois em mim tenho a parte desejada.\n\nSe nela está minha alma transformada,\nQue mais deseja o corpo de alcançar?\nEm si somente pode descansar,\nPois com ele tal alma está liada.\n\nMas esta linda e pura semideia,\nQue como o acidente em seu sojeito,\nAssi com a alma minha se conforma;\n\nEstá no pensamento como ideia;\nE o vivo e puro amor de que sou feito,\nComo a matéria simples busca a forma."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, X, p. 6.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Transforma-se_o_amador_na_cousa_amada"}]}},
"luis-de-camoes-soneto-passo-por-meus-trabalhos-tao-isento": {"t":["Passo por meus trabalhos tão isento\nDe sentimento grande nem pequeno,\nQue só por a vontade com que peno\nMe fica Amor devendo mais tormento.\n\nMas vai-me Amor matando tanto a tento,\nTemperando a triaga co'o veneno,\nQue do penar a ordem desordeno,\nPorque não mo consente o sofrimento.\n\nPorém se esta fineza o Amor sente\nE pagar-me meu mal com mal pretende,\nTorna-me com prazer como ao sol neve.\n\nMas se me vê co'os males tão contente,\nFaz-se avaro da pena, porque entende\nQue quanto mais me paga, mais me deve."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XI, p. 6.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Passo_por_meus_trabalhos_t%C3%A3o_isento"}]}},
"luis-de-camoes-soneto-em-flor-vos-arrancou-de-entao-crescida": {"t":["Em flor vos arrancou, de então crescida,\n(Ah Senhor Dom Antônio!) a dura sorte\nDonde fazendo andava o braço forte\nA fama dos antiguos esquecida.\n\nUma só razão tenho conhecida\nCom que tamanha mágoa se conforte:\nQue se no Mundo havia honrada morte,\nNão podíeis vós ter mais larga vida\n\nSe meus humildes versos podem tanto\nQue co'o desejo meu se iguale a arte,\nEspecial matéria me sereis\n\nE celebrado em triste e longo canto,\nSe morrestes nas mãos do fero Marte,\nNa memória das gentes vivireis."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XII, p. 7.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nO Wikisource lista este soneto também como «À morte de D. António de Noronha»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Em_flor_vos_arrancou,_de_então_crescida"}]}},
"luis-de-camoes-soneto-n-um-jardim-adornado-de-verdura": {"t":["N'um jardim adornado de verdura,\nQue esmaltavam por cima várias flores,\nEntrou um dia a deusa dos amores,\nCom a deusa da caça e da espessura.\n\nDiana tomou logo ũa rosa pura,\nVênus um roxo lírio, dos melhores;\nMas excediam muito às outras flores\nAs violas na graça e formosura.\n\nPerguntam a Cupido, que ali estava,\nQual de aquelas três flores tomaria\nPor mais suave e pura, e mais formosa.\n\nSorrindo-se o menino lhes tornava:\nTodas formosas são; mas eu queria\nViola antes que lírio, nem que rosa."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XIII, p. 7.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/N'hum_jardim_adornado_de_verdura"}]}},
"luis-de-camoes-soneto-todo-animal-da-calma-repousava": {"t":["Todo animal da calma repousava,\nSó Liso o ardor dela não sentia;\nQue o repouso do fogo, em que ele ardia,\nConsistia na Ninfa que buscava.\n\nOs montes parecia que abalava\nO triste som das mágoas que dizia:\nMas nada o duro peito comovia,\nQue na vontade de outro posto estava.\n\nCansado já de andar por a espessura,\nNo tronco de uma faia, por lembrança,\nEscreve estas palavras de tristeza\n\nNunca ponha ninguém sua esperança\nEm peito feminil, que de natura\nSomente em ser mudável tem firmeza."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XIV, p. 8.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\nO índice do Wikisource dá o primeiro verso como 'Todo o animal da calma repousava'; a ed. de 1843 traz 'Todo animal'.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Todo_o_animal_da_calma_repousava"}]}},
"luis-de-camoes-soneto-busque-amor-novas-artes-novo-engenho": {"t":["Busque Amor novas artes, novo engenho\nPara matar-me, e novas esquivanças;\nQue não pode tirar-me as esperanças,\nPois mal me tirará o que eu não tenho.\n\nOlhai de que esperanças me mantenho!\nVede que perigosas seguranças!\nPois não temo contrastes nem mudanças,\nAndando em bravo mar, perdido o lenho.\n\nMas conquanto não pode haver desgosto\nOnde esperança falta, lá me esconde\nAmor um mal, que mata e não se vê.\n\nQue dias há que na alma me tem posto\nUm não sei quê, que nasce não sei onde;\nVem não sei como; e dói não sei por quê."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XV, p. 8.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Busque_Amor_novas_artes,_novo_engenho"}]}},
"luis-de-camoes-soneto-quem-ve-senhora-claro-e-manifesto": {"t":["Quem vê, Senhora, claro e manifesto\nO lindo ser de vossos olhos belos,\nSe não perder a vista só com vê-los,\nJá não paga o que deve a vosso gesto.\n\nEste me parecia preço honesto;\nMas eu, por de vantagem merecê-los,\nDei mais a vida e alma por querê-los;\nDonde já me não fica mais de resto.\n\nAssi que alma, que vida, que esperança,\nE que quanto for meu, é tudo vosso:\nMas de tudo o interesse eu só o levo.\n\nPorque é tamanha bem-aventurança\nO dar-vos quanto tenho, e quanto posso,\nQue quanto mais vos pago, mais vos devo."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XVI, p. 9.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quem_vê,_Senhora,_claro_e_manifesto"}]}},
"luis-de-camoes-soneto-quando-da-bela-vista-e-doce-riso": {"t":["Quando da bela vista e doce riso\nTomando estão meus olhos mantimento,\nTão elevado sinto o pensamento,\nQue me faz ver na terra o Paraíso.\n\nTanto do bem humano estou diviso,\nQue qualquer outro bem julgo por vento:\nAssi que em termo tal, segundo sento,\nPouco vem a fazer quem perde o siso.\n\nEm louvar-vos, Senhora, não me fundo;\nPorque quem vossas graças claro sente,\nSentirá que não pode conhecê-las.\n\nPois de tanta estranheza sois ao mundo,\nQue não é de estranhar, Dama excelente,\nQue quem vos fez, fizesse céu e estrelas."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XVII, p. 9.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quando_da_bella_vista_e_doce_riso"}]}},
"luis-de-camoes-soneto-doces-lembrancas-da-passada-gloria": {"t":["Doces lembranças da passada glória,\nQue me tirou fortuna roubadora,\nDeixai-me descansar em paz um'hora,\nQue comigo ganhais pouca vitória.\n\nImpressa tenho na alma larga história\nDeste passado bem, que nunca fora;\nOu fora, e não passara: mas já agora\nEm mi não pode haver mais que a memória.\n\nVivo em lembranças, morro de esquecido\nDe quem sempre devera ser lembrado,\nSe lhe lembrara estado tão contente.\n\nOh quem tornar pudera a ser nascido!\nSoubera-me lograr do bem passado,\nSe conhecer soubera o mal presente."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XVIII, p. 10.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Doces_lembranças_da_passada_gloria"}]}},
"luis-de-camoes-soneto-alma-minha-gentil-que-te-partiste": {"t":["Alma minha gentil, que te partiste\nTão cedo desta vida descontente,\nRepousa lá no Céu eternamente,\nE viva eu cá na terra sempre triste.\n\nSe lá no assento Etéreo, onde subiste,\nMemória desta vida se consente,\nNão te esqueças de aquele amor ardente,\nQue já nos olhos meus tão puro viste.\n\nE se vires que pode merecer-te\nAlgũa cousa a dor que me ficou\nDa mágoa, sem remédio, de perder-te;\n\nRoga a Deus que teus anos encurtou,\nQue tão cedo de cá me leve a ver-te,\nQuão cedo de meus olhos te levou."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XIX, p. 10.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nVariantes da 1.ª edição (Rhythmas, 1595, soneto XIII): «Não te esqueça daquelle amor ardente», «Quam cedo de meus olhos te levou»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Obras_completas_de_Luis_de_Camões/Alma_minha_gentil,_que_te_partiste"}]}},
"luis-de-camoes-soneto-n-um-bosque-que-das-ninfas-se-habitava": {"t":["N'um bosque, que das Ninfas se habitava,\nSibela, Ninfa linda, andava um dia;\nE subida em uma árvore sombria,\nAs amarelas flores apanhava.\n\nCupido, que ali sempre costumava\nA vir passar a sesta à sombra fria,\nEm um ramo arco e setas, que trazia,\nAntes que adormecesse, pendurava.\n\nA Ninfa, como idôneo tempo vira\nPara tamanha empresa, não dilata;\nMas com as armas foge ao moço esquivo.\n\nAs setas traz nos olhos, com que tira.\nÓ Pastores! fugi, que a todos mata,\nSenão a mim, que de matar-me vivo."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XX, p. 11.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nPonto final do v. 8 restituído conforme o Gutenberg n.º 31509 (falta na transcrição do Wikisource)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/N'hum_bosque,_que_das_Nymphas_se_habitava"}]}},
"luis-de-camoes-soneto-os-reinos-e-os-imperios-poderosos": {"t":["Os Reinos e os Impérios poderosos,\nQue em grandeza no mundo mais cresceram;\nOu por valor de esforço floreceram,\nOu por Barões nas letras espantosos.\n\nTeve Grécia Temístocles famosos;\nOs Cipiões a Roma engrandeceram;\nDoze Pares a França glória deram;\nCides a Espanha, e Laras belicosos.\n\nAo nosso Portugal, que agora vemos\nTão diferente de seu ser primeiro,\nOs vossos deram honra e liberdade.\n\nE em vós, grão sucessor e novo herdeiro\nDo Braganção Estado, há mil extremos\nIguais ao sangue, e mores que a idade."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXI, p. 11.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Os_Reinos_e_os_Imperios_poderosos"}]}},
"luis-de-camoes-soneto-de-vos-me-parto-o-vida-e-em-tal-mudanca": {"t":["De vós me parto, ó vida, e em tal mudança\nSinto vivo da morte o sentimento.\nNão sei para que é ter contentamento,\nSe mais há de perder quem mais alcança.\n\nMas dou-vos esta firme segurança:\nQue posto que me mate o meu tormento,\nPor as águas do eterno esquecimento\nSegura passará minha lembrança\n\nAntes sem vós meus olhos se entristeçam,\nQue com cousa outra alguma se contentem:\nAntes os esqueçais, que vos esqueçam.\n\nAntes nesta lembrança se atormentem,\nQue com esquecimento desmereçam\nA glória que em sofrer tal pena sentem."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXII, p. 12.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nOutras edições: «De vós me aparto, ó vida! Em tal mudança»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/De_vós_me_parto,_ó_vida,_e_em_tal_mudança"}]}},
"luis-de-camoes-soneto-cara-minha-inimiga-em-cuja-mao": {"t":["Cara minha inimiga, em cuja mão\nPôs meus contentamentos a ventura,\nFaltou-te a ti na terra sepultura,\nPorque me falte a mi consolação.\n\nEternamente as águas lograrão\nA tua peregrina formosura:\nMas enquanto me a mim a vida dura,\nSempre viva em minha alma te acharão.\n\nE se meus rudos versos podem tanto,\nQue possam prometer-te longa história\nDe aquele amor tão puro e verdadeiro;\n\nCelebrada serás sempre em meu canto:\nPorque enquanto no mundo houver memória,\nSerá a minha escritura o teu letreiro."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXIII, p. 12.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA fonte traz «Chara» (ch = c), atualizado para «Cara»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Chara_minha_inimiga,_em_cuja_mão"}]}},
"luis-de-camoes-soneto-aquela-triste-e-leda-madrugada": {"t":["Aquela triste e leda madrugada,\nCheia toda de mágoa e de piedade,\nEnquanto houver no mundo saudade\nQuero que seja sempre celebrada.\n\nEla só, quando amena e marchetada\nSaía, dando à terra claridade,\nViu apartar-se de uma outra vontade,\nQue nunca poderá ver-se apartada\n\nEla só viu as lágrimas em fio,\nQue de uns e de outros olhos derivadas,\nJuntando-se, formaram largo rio\n\nEla ouviu as palavras magoadas,\nQue puderam tornar o fogo frio,\nE dar descanso às almas condenadas."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXIV, p. 13.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Aquella_triste_e_leda_madrugada"}]}},
"luis-de-camoes-soneto-em-formosa-leteia-se-confia": {"t":["Em formosa Leteia se confia,\nPor onde vaidade tanta alcança,\nQue, tornada em soberba a confiança,\nCom os deuses celestes competia.\n\nPorque não fosse avante esta ousadia,\n(Que nascem muitos erros da tardança)\nEm efeito puseram a vingança\nQue tamanha doudice merecia.\n\nMas Oleno, perdido por Leteia,\nNão lhe sofrendo Amor que suportasse\nDuro castigo em tanta formosura,\n\nQuis a pena tomar da culpa alheia:\nMas, porque a Morte Amor não apartasse,\nAmbos tornados são em pedra dura."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXVI, p. 14.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nOutras edições: «Em fermosa Leteia se confia»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Em_formosa_Lethea_se_confia"}]}},
"luis-de-camoes-soneto-males-que-contra-mim-vos-conjurastes": {"t":["Males, que contra mim vos conjurastes,\nQuanto há de durar tão duro intento?\nSe dura, porque dure meu tormento,\nBaste-vos quanto já me atormentastes.\n\nMas se assi porfiais, porque cuidastes\nDerribar o meu alto pensamento,\nMais pode a causa dele, em que o sustento,\nQue vós, que dela mesma o ser tomastes.\n\nE pois vossa tenção com minha morte\nÉ de acabar o mal destes amores,\nDai já fim a tormento tão comprido.\n\nAssi de ambos contente será a sorte;\nEm vós por acabar-me, vencedores,\nEm mim porque acabei de vós vencido."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXVII, p. 14.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nO Anexo do Wikisource dá o 1.º verso como «Males, que contra mi vos conjurastes»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Males,_que_contra_mim_vos_conjurastes"}]}},
"luis-de-camoes-soneto-esta-se-a-primavera-trasladando": {"t":["Está-se a Primavera trasladando\nEm vossa vista deleitosa e honesta;\nNas belas faces, e na boca e testa,\nCecéns, rosas, e cravos debuxando.\n\nDe sorte, vosso gesto matizando,\nNatura quanto pode manifesta,\nQue o monte, o campo, o rio, e a floresta,\nSe estão de vós, Senhora, namorando.\n\nSe agora não quereis que quem vos ama\nPossa colher o fruto destas flores,\nPerderão toda a graça os vossos olhos.\n\nPorque pouco aproveita, linda Dama,\nQue semeasse o Amor em vós amores,\nSe vossa condição produze abrolhos."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXVIII, p. 15.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Est%C3%A1-se_a_Primavera_trasladando"}]}},
"luis-de-camoes-soneto-sete-anos-de-pastor-jaco-servia": {"t":["Sete anos de pastor Jacó servia\nLabão, pai de Raquel, serrana bela:\nMas não servia ao pai, servia a ela,\nQue a ela só por prêmio pertendia.\n\nOs dias na esperança de um só dia\nPassava, contentando-se com vê-la:\nPorém o pai, usando de cautela,\nEm lugar de Raquel lhe deu a Lia.\n\nVendo o triste Pastor que com enganos\nAssi lhe era negada a sua Pastora,\nComo se a não tivera merecida;\n\nComeçou a servir outros sete anos,\nDizendo: Mais servira, se não fora\nPara tão longo amor tão curta a vida."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXIX, p. 15.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA fonte grafa 'Jacob'; na versão atualizada, 'Jacó' (norma brasileira), também oxítono.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Sete_annos_de_pastor_Jacob_servia"}]}},
"luis-de-camoes-soneto-esta-o-lascivo-e-doce-passarinho": {"t":["Está o lascivo e doce passarinho\nCom o biquinho as penas ordenando;\nO verso sem medida, alegre e brando,\nDespedindo no rústico raminho.\n\nO cruel caçador, que do caminho\nSe vem calado e manso desviando,\nCom pronta vista a seta endireitando,\nLhe dá no Estígio Lago eterno ninho.\n\nDesta arte o coração, que livre andava,\n(Posto que já de longe destinado)\nOnde menos temia, foi ferido.\n\nPorque o frecheiro cego me esperava,\nPara que me tomasse descuidado,\nEm vossos claros olhos escondido."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXX, p. 16.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Est%C3%A1_o_lascivo_e_doce_passarinho"}]}},
"luis-de-camoes-soneto-pede-o-desejo-dama-que-vos-veja": {"t":["Pede o desejo, Dama, que vos veja:\nNão entende o que pede; está enganado.\nÉ este amor tão fino e tão delgado,\nQue quem o tem, não sabe o que deseja.\n\nNão há cousa, a qual natural seja,\nQue não queira perpétuo o seu estado.\nNão quer logo o desejo o desejado,\nSó porque nunca falte onde sobeja.\n\nMas este puro afeto em mim se dana:\nQue, como a grave pedra tem por arte\nO centro desejar da natureza;\n\nAssi meu pensamento por a parte,\nQue vai tomar de mi, terreste e humana,\nFoi, Senhora, pedir esta baixeza."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXXI, p. 16.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\nV. 5: a fonte traz «qüal», com trema que indica a diérese qu-al (com sinalefa em «cousa, a»); no texto atualizado, «qual» (sem trema, como pede a regra para qü); o verso mede 10 sílabas nas duas leituras.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Pede_o_desejo,_Dama,_que_vos_veja"}]}},
"luis-de-camoes-soneto-porque-quereis-senhora-que-ofereca": {"t":["Porque quereis, Senhora, que ofereça\nA vida a tanto mal como padeço?\nSe vos nasce do pouco que eu mereço,\nBem por nascer está quem vos mereça.\n\nEntendei que por muito que vos peça,\nPoderei merecer quanto vos peço;\nPois não consente amor que em baixo preço\nTão alto pensamento se conheça.\n\nAssi que a paga igual de minhas dores\nCom nada se restaura; mas devês-ma\nPor ser capaz de tantos desfavores.\n\nE se o valor de vossos amadores\nHouver de ser igual convosco mesma,\nVós só convosco mesma andai de amores."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXXII, p. 17.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC CDC)\n\n**Notas sobre o texto.**\n\nV. 10: «devêsma» (fonte) = devês-ma (deveis-ma), rima com «mesma»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Porque_quereis,_Senhora,_que_offere%C3%A7a"}]}},
"luis-de-camoes-soneto-se-tanta-pena-tenho-merecida": {"t":["Se tanta pena tenho merecida\nEm pago de sofrer tantas durezas;\nProvai, Senhora, em mi vossas cruezas,\nQue aqui tendes uma alma oferecida.\n\nNela experimentai, se sois servida,\nDesprezos, desfavores e asperezas;\nQue mores sofrimentos e firmezas\nSustentarei na guerra desta vida.\n\nMas contra vossos olhos quais serão?\nÉ preciso que tudo se lhes renda;\nMas porei por escudo o coração.\n\nPorque em tão dura e áspera contenda\nÉ bem que, pois não acho defensão,\nCom meter-me nas lanças me defenda"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXXIII, p. 17.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Se_tanta_pena_tenho_merecida"}]}},
"luis-de-camoes-soneto-quando-o-sol-encoberto-vai-mostrando": {"t":["Quando o sol encoberto vai mostrando\nAo mundo a luz quieta e duvidosa,\nAo longo de uma praia deleitosa\nVou na minha inimiga imaginando.\n\nAqui a vi os cabelos concertando;\nAli co'a mão na face, tão formosa;\nAqui falando alegre, ali cuidosa;\nAgora estando queda, agora andando.\n\nAqui esteve sentada, ali me viu,\nErguendo aqueles olhos, tão isentos;\nComovida aqui um pouco, ali segura.\n\nAqui se entristeceu, ali se riu:\nE, enfim, nestes cansados pensamentos\nPasso esta vida vã, que sempre dura."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXXIV, p. 18.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quando_o_sol_encoberto_vai_mostrando"}]}},
"luis-de-camoes-soneto-um-mover-de-olhos-brando-e-piedoso": {"t":["Um mover de olhos, brando e piedoso,\nSem ver de quê; um riso brando e honesto,\nQuase forçado; um doce e humilde gesto,\nDe qualquer alegria duvidoso:\n\nUm despejo quieto e vergonhoso;\nUm repouso gravíssimo e modesto;\nUma pura bondade, manifesto\nIndício da alma, limpo e gracioso:\n\nUm encolhido ousar; uma brandura;\nUm medo sem ter culpa; um ar sereno;\nUm longo e obediente sofrimento:\n\nEsta foi a celeste formosura\nDa minha Circe, e o mágico veneno\nQue pôde transformar meu pensamento"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXXV, p. 18.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nO índice do Wikisource traz 'piadoso' no primeiro verso; a ed. de 1843, 'piedoso'.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Hum_mover_de_olhos,_brando_e_piedoso"}]}},
"luis-de-camoes-soneto-tomou-me-vossa-vista-soberana": {"t":["Tomou-me vossa vista soberana\nAdonde tinha as armas mais à mão,\nPor mostrar a quem busca defensão\nContra esses belos olhos, que se engana.\n\nPor ficar da vitória mais ufana,\nDeixou-me armar primeiro da razão.\nBem salvar-me cuidei, mas foi em vão,\nQue contra o Céu não val defensa humana.\n\nContudo, se vos tinha prometido\nO vosso alto destino esta vitória,\nSer-vos ela bem pouca está entendido.\n\nPois, inda que eu me achasse apercebido,\nNão levais de vencer-me grande glória,\nEu a levo maior de ser vencido."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXXVI, p. 19.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC CDC)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Tomou-me_vossa_vista_soberana"}]}},
"luis-de-camoes-soneto-nao-passes-caminhante-quem-me-chama": {"t":["Não passes, caminhante. Quem me chama?\nŨa memória nova e nunca ouvida,\nDe um que trocou finita e humana vida\nPor divina, infinita, e clara fama.\n\nQuem é, que tão gentil louvor derrama?\nQuem derramar seu sangue não duvida,\nPor seguir a bandeira esclarecida\nDe um capitão de Cristo que mais ama.\n\nDitoso fim, ditoso sacrifício,\nQue a Deus se fez e ao mundo juntamente!\nPregoando direi tão alta sorte.\n\nMais poderás contar a toda a gente\nQue sempre deu na vida claro indício\nDe vir a merecer tão santa morte."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXXVII, p. 19.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/N%C3%A3o_passes,_caminhante._Quem_me_chama?"}]}},
"luis-de-camoes-soneto-formosos-olhos-que-na-idade-nossa": {"t":["Formosos olhos, que na idade nossa\nMostrais do Céu certíssimos sinais,\nSe quereis conhecer quanto possais,\nOlhai-me a mim, que sou feitura vossa.\n\nVereis que do viver me desapossa\nAquele riso com que a vida dais:\nVereis como de Amor não quero mais,\nPor mais que o tempo corra, o dano possa.\n\nE se ver-vos nesta alma, enfim, quiserdes,\nComo em um claro espelho, ali vereis\nTambém a vossa angélica e serena.\n\nMas eu cuido que, só por me não verdes,\nVer-vos em mim, Senhora, não quereis:\nTanto gosto levais de minha pena!"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXXVIII, p. 20.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nO Anexo do Wikisource dá o 1.º verso como «Fermosos olhos que na idade nossa» (a ed. de 1843 normaliza fermoso > formoso)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Formosos_olhos,_que_na_idade_nossa"}]}},
"luis-de-camoes-soneto-o-fogo-que-na-branda-cera-ardia": {"t":["O fogo que na branda cera ardia,\nVendo o rosto gentil, que eu na alma vejo,\nSe acendeu de outro fogo do desejo\nPor alcançar a luz que vence o dia.\n\nComo de dous ardores se encendia,\nDa grande impaciência fez despejo,\nE remetendo com furor sobejo,\nVos foi beijar na parte onde se via.\n\nDitosa aquela flama que se atreve\nA apagar seus adores e tormentos\nNa vista a quem o sol temores deve!\n\nNamoram-se, Senhora, os Elementos\nDe vós, e queima o fogo aquela neve\nQue queima corações e pensamentos."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XXXIX, p. 20.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nV. 10: «adores» está assim na ed. de 1843 e no Gutenberg; provável erro por «ardores» (mantido)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/O_fogo_que_na_branda_cera_ardia"}]}},
"luis-de-camoes-soneto-alegres-campos-verdes-arvoredos": {"t":["Alegres campos, verdes arvoredos,\nClaras e frescas águas de cristal,\nQue em vós os debuxais ao natural,\nDiscorrendo da altura dos rochedos:\n\nSilvestres montes, ásperos penedos\nCompostos de concerto desigual;\nSabei que sem licença de meu mal\nJá não podeis fazer meus olhos ledos.\n\nE pois já me não vedes como vistes,\nNão me alegrem verduras deleitosas,\nNem águas que correndo alegres vêm.\n\nSemearei em vós lembranças tristes,\nRegar-vos-ei com lágrimas saudosas,\nE nascerão saudades de meu bem."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XL, p. 21.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\n«Regar-vos-hei» atualizado para «Regar-vos-ei» (a mesóclise é do original); «vem» (plural) atualizado para «vêm»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Alegres_campos,_verdes_arvoredos"}]}},
"luis-de-camoes-soneto-quantas-vezes-do-fuso-se-esquecia": {"t":["Quantas vezes do fuso se esquecia\nDaliana, banhando o lindo seio,\nOutras tantas de um áspero receio\nSalteado Laurênio a cor perdia.\n\nEla, que a Sílvio mais que a si queria,\nPara podê-lo ver não tinha meio.\nOra como curara o mal alheio\nQuem o seu mal tão mal curar podia?\n\nEle, que viu tão clara esta verdade,\nCom soluços dizia (que a espessura\nInclinavam, de mágoa, a piedade):\n\nComo pode a desordem da natura\nFazer tão diferentes na vontade\nAos que fez tão conformes na ventura?"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XLI, p. 21.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quantas_vezes_do_fuso_se_esquecia"}]}},
"luis-de-camoes-soneto-lindo-e-sutil-trancado-que-ficaste": {"t":["Lindo e sutil trançado, que ficaste\nEm penhor do remédio que mereço,\nSe só contigo, vendo-te, endoudeço,\nQue fora co'os cabelos que apertaste?\n\nAquelas tranças de ouro que ligaste,\nQue os raios do sol têm em pouco preço,\nNão sei se ou para engano do que peço,\nOu para me matar as desataste.\n\nLindo trançado, em minhas mãos te vejo,\nE por satisfação de minhas dores,\nComo quem não tem outra, hei de tomar-te.\n\nE se não for contente o meu desejo,\nDir-lhe-ei que nesta regra dos amores\nPor o todo também se toma a parte."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XLII, p. 22.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\n«tẽe» da fonte = têm (sujeito: aquelas tranças)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Lindo_e_subtil_tran%C3%A7ado,_que_ficaste"}]}},
"luis-de-camoes-soneto-o-cisne-quando-sente-ser-chegada": {"t":["O cisne quando sente ser chegada\nA hora que põe termo à sua vida,\nHarmonia maior, com voz sentida,\nLevanta por a praia inabitada.\n\nDeseja lograr vida prolongada,\nE dela está chorando a despedida:\nCom grande saudade da partida,\nCelebra o triste fim desta jornada.\n\nAssi, Senhora minha, quando eu via\nO triste fim que davam meus amores,\nEstando posto já no extremo fio;\n\nCom mais suave acento de harmonia\nDescantei por os vossos desfavores\nLa vuestra falsa fe, y el amor mío."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XLIII, p. 22.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nV. 14 em castelhano («mio» > «mío» na grafia atual)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/O_cysne_quando_sente_ser_chegada"}]}},
"luis-de-camoes-soneto-por-os-raros-extremos-que-mostrou": {"t":["Por os raros extremos que mostrou\nEm sábia Palas, Vênus em formosa,\nDiana em casta, Juno em animosa,\nÁfrica, Europa e Ásia as adorou.\n\nAquele saber grande que juntou\nEsprito e corpo em liga generosa,\nEsta mundana máquina lustrosa,\nDe sós quatro elementos fabricou.\n\nMas fez maior milagre a natureza\nEm vós, Senhoras, pondo em cada ũa\nO que por todas quatro repartiu.\n\nA vós seu resplandor deu sol e lũa:\nA vós com viva luz, graça e pureza,\nAr, Fogo, Terra e Água vos serviu."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XLIV, p. 23.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\nO Anexo do Wikisource lista este soneto pela lição moderna «Pelos extremos raros que mostrou»; a ed. de 1843 traz «Por os raros extremos que mostrou»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Por_os_raros_extremos_que_mostrou"}]}},
"luis-de-camoes-soneto-tomava-daliana-por-vinganca": {"t":["Tomava Daliana por vingança\nDa culpa do pastor que tanto amava,\nCasar com Gil vaqueiro; e em si vingava\nO erro alheio, e pérfida esquivança.\n\nA discrição segura, a confiança\nDas rosas que o seu rosto debuxava,\nO descontentamento lhas mudava;\nQue tudo muda uma áspera mudança.\n\nGentil planta disposta em seca terra;\nLindo fruto de dura mão colhido;\nLembranças de outro amor, e fé perjura,\n\nTornaram verde prado em serra dura;\nInteresse enganoso, amor fingido,\nFizeram desditosa a formosura."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XLV, p. 23.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE EDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Tomava_Daliana_por_vingança"}]}},
"luis-de-camoes-soneto-grao-tempo-ha-ja-que-soube-da-ventura": {"t":["Grão tempo há já que soube da Ventura\nA vida que me tinha destinada;\nQue a longa experiência da passada\nMe dava claro indício da futura.\n\nAmor fero e cruel, Fortuna escura,\nBem tendes vossa força exprimentada:\nAssolai, destruí, não fique nada;\nVingai-vos desta vida, que inda dura.\n\nSoube Amor da Ventura, que a não tinha,\nE porque mais sentisse a falta dela,\nDe imagens impossíveis me mantinha.\n\nMas vós, Senhora, pois que minha estrela\nNão foi melhor, vivei nesta alma minha;\nQue não tem a Fortuna poder nela."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XLVI, p. 24.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Gr%C3%A3o_tempo_ha_ja_que_soube_da_Ventura"}]}},
"luis-de-camoes-soneto-se-somente-hora-alguma-em-vos-piedade": {"t":["Se somente hora alguma em vós piedade\nDe tão longo tormento se sentira,\nAmor sofrera mal que eu me partira\nDe vossos olhos, minha Saudade.\n\nApartei-me de vós, mas a vontade,\nQue por o natural na alma vos tira,\nMe faz crer que esta ausência é de mentira;\nPorém venho a provar que é de verdade.\n\nIr-me-ei, Senhora; e neste apartamento\nLágrimas tristes tomarão vingança\nNos olhos de quem fostes mantimento.\n\nDesta arte darei vida a meu tormento;\nQue, enfim, cá me achará minha lembrança\nSepultado no vosso esquecimento."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XLVII, p. 24.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC CDC)\n\n**Notas sobre o texto.**\n\nO índice do Wikisource dá o primeiro verso como 'Se algũa hora em vós a piedade' (outra lição); a ed. de 1843 traz 'Se somente hora alguma em vós piedade'.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Se_somente_hora_alguma_em_vós_piedade"}]}},
"luis-de-camoes-soneto-oh-como-se-me-alonga-de-ano-em-ano": {"t":["Oh como se me alonga de ano em ano\nA peregrinação cansada minha!\nComo se encurta, e como ao fim caminha\nEste meu breve e vão discurso humano!\n\nMingoando a idade vai, crescendo o dano;\nPerdeu-se-me um remédio, que inda tinha:\nSe por experiência se adivinha,\nQualquer grande esperança é grande engano.\n\nCorro após este bem que não se alcança;\nNo meio do caminho me falece;\nMil vezes caio, e perco a confiança.\n\nQuando ele foge, eu tardo; e na tardança,\nSe os olhos ergo a ver se inda aparece,\nDa vista se me perde, e da esperança."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XLVIII, p. 25.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC CDC)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Oh_como_se_me_alonga_de_anno_em_ano"}]}},
"luis-de-camoes-soneto-amor-com-a-esperanca-ja-perdida": {"t":["Amor, com a esperança já perdida\nTeu soberano templo visitei:\nPor sinal do naufrágio que passei,\nEm lugar dos vestidos, pus a vida.\n\nQue mais queres de mi, pois destruída\nMe tens a glória toda que alcancei?\nNão cuides de render-me; que não sei\nTornar a entrar-me onde não há saída.\n\nVês aqui a vida, e a alma, e a esperança,\nDoces despojos de meu bem passado,\nEnquanto o quis aquela que eu adoro.\n\nNelas podes tomar de mi vingança:\nE se te queres inda mais vingado,\nContenta-te co'as lágrimas que choro."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, L, p. 26.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nO Wikisource lista este soneto como «Amor, co a esperança já perdida»; a ed. de 1843 traz «com a»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Amor,_com_a_esperança_ja_perdida"}]}},
"luis-de-camoes-soneto-apolo-e-as-nove-musas-descantando": {"t":["Apolo e as nove Musas, descantando\nCom a dourada lira, me influíam\nNa suave harmonia que faziam,\nQuando tomei a pena, começando:\n\nDitoso seja o dia e hora, quando\nTão delicados olhos me feriam!\nDitosos os sentidos que sentiam\nEstar-se em seu desejo traspassando!\n\nAssi cantava, quando Amor virou\nA roda à esperança, que corria\nTão ligeira, que quase era invisíbil.\n\nConverteu-se-me em noite o claro dia;\nE se alguma esperança me ficou,\nSerá de maior mal, se for possíbil."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LI, p. 26.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\n«invisibil» e «possibil» (formas latinizantes, em rima) mantidas, acentuadas pela norma: «invisíbil», «possíbil»; outras edições: «discantando»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Apollo_e_as_nove_Musas,_descantando"}]}},
"luis-de-camoes-soneto-lembrancas-saudosas-se-cuidais": {"t":["Lembranças saudosas, se cuidais\nDe me acabar a vida neste estado,\nNão vivo com meu mal tão enganado,\nQue não espere dele muito mais.\n\nDe longo tempo já me costumais\nA viver de algum bem desesperado:\nJá tenho co'a Fortuna concertado\nDe sofrer os tormentos que me dais.\n\nAtada ao remo tenho a paciência\nPara quantos desgostos der a vida;\nCuide quanto quiser o pensamento.\n\nQue pois não posso ter mais resistência\nPara tão dura queda, de subida,\nAparar-lhe-ei debaixo o sofrimento."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LII, p. 27.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Lembran%C3%A7as_saudosas,_se_cuidais"}]}},
"luis-de-camoes-soneto-apartava-se-nise-de-montano": {"t":["Apartava-se Nise de Montano,\nEm cuja alma, partindo-se, ficava;\nQue o pastor na memória a debuxava,\nPor poder sustentar-se deste engano.\n\nPor uma praia do Índico Oceano\nSobre o curvo cajado se encostava,\nE os olhos por as águas alongava,\nQue pouco se doíam de seu dano.\n\nPois com tamanha mágoa e saudade,\n(Dizia) quis deixar-me a que eu adoro,\nPor testimunhas tomo céu e estrelas.\n\nMas se em vós, ondas, mora piedade,\nLevai também as lágrimas que choro,\nPois assi me levais a causa delas."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LIII, p. 27.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\n«testimunhas» (forma antiga) mantida.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Apartava-se_Nise_de_Montano"}]}},
"luis-de-camoes-soneto-quando-vejo-que-meu-destino-ordena": {"t":["Quando vejo que meu destino ordena\nQue, por me exprimentar, de vós me aparte,\nDeixando de meu bem tão grande parte,\nQue a mesma culpa fica grave pena;\n\nO duro desfavor, que me condena,\nQuando por a memória se reparte,\nEndurece os sentidos de tal arte\nQue a dor da ausência fica mais pequena.\n\nMas como pode ser que na mudança\nD'aquilo que mais quero, estê tão fora\nDe me não apartar também da vida?\n\nEu refrearei tão áspera esquivança:\nPorque mais sentirei partir, Senhora,\nSem sentir muito a pena da partida."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LIV, p. 28.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\n'estê' (v10), forma antiga do conjuntivo de estar (= esteja), mantida como na fonte.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quando_vejo_que_meu_destino_ordena"}]}},
"luis-de-camoes-soneto-naiades-vos-que-os-rios-habitais": {"t":["Náiades, vós que os rios habitais,\nQue os saudosos campos vão regando,\nDe meus olhos vereis estar manando\nOutros que quase aos vossos são iguais.\n\nDríades, que com seta sempre andais\nOs fugitivos cervos derribando,\nOutros olhos vereis, que triunfando\nDerribam corações, que valem mais.\n\nDeixai logo as aljavas e águas frias,\nE vinde, Ninfas belas, se quereis,\nA ver como de uns olhos nascem mágoas.\n\nNotareis como em vão passam os dias;\nMas em vão não vireis, porque achareis\nNos seus as setas, e nos meus as águas."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LVI, p. 29.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Naiades,_v%C3%B3s_que_os_rios_habitais"}]}},
"luis-de-camoes-soneto-mudam-se-os-tempos-mudam-se-as-vontades": {"t":["Mudam-se os tempos, mudam-se as vontades,\nMuda-se o ser, muda-se a confiança:\nTodo o mundo é composto de mudança,\nTomando sempre novas qualidades.\n\nContinuamente vemos novidades,\nDiferentes em tudo da esperança:\nDo mal ficam as mágoas na lembrança,\nE do bem (se algum houve) as saudades.\n\nO tempo cobre o chão de verde manto,\nQue já coberto foi de neve fria,\nE em mi converte em choro o doce canto.\n\nE afora este mudar-se cada dia,\nOutra mudança faz de mor espanto,\nQue não se muda já como soía."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LVII, p. 29.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\n«sohia» (fonte) = soía, 3 sílabas (so-í-a)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Mud%C3%A3o-se_os_tempos,_mud%C3%A3o-se_as_vontades"}]}},
"luis-de-camoes-soneto-se-as-penas-com-que-amor-tao-mal-me-trata": {"t":["Se as penas com que Amor tão mal me trata\nPermitirem que eu tanto viva delas,\nQue veja escuro o lume das estrelas,\nEm cuja vista o meu se acende e mata;\n\nE se o tempo, que tudo desbarata,\nSecar as frescas rosas, sem colhê-las,\nDeixando a linda cor das tranças belas\nMudada de ouro fino em fina prata;\n\nTambém, Senhora, então vereis mudado\nO pensamento e a aspereza vossa,\nQuando não sirva já sua mudança.\n\nVer-vos-eis suspirar por o passado,\nEm tempo quando executar-se possa\nNo vosso arrepender minha vingança."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LVIII, p. 30.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Se_as_penas_com_que_Amor_tão_mal_me_trata"}]}},
"luis-de-camoes-soneto-quem-jaz-no-grao-sepulcro-que-descreve": {"t":["Quem jaz no grão sepulcro, que descreve\nTão ilustres sinais no forte escudo?\nNinguém; que nisso, enfim se torna tudo:\nMas foi quem tudo pôde e tudo teve.\n\nFoi Rei? Fez tudo quanto a Rei se deve:\nPôs na guerra e na paz devido estudo.\nMas quão pesado foi ao Mouro rudo,\nTanto lhe seja agora a terra leve.\n\nAlexandro será? Ninguém se engane:\nMais que o adquirir, o sustentar estima.\nSerá Adriano grão Senhor do mundo?\n\nMais observante foi da Lei de cima.\nÉ Numa? Numa não, mas é Joane.\nDe Portugal Terceiro sem segundo."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LIX, p. 30.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\nO Wikisource lista este soneto como «À sepultura del-Rei D. João III»; formas «Alexandro» e «Joane» mantidas; «Hadriano» atualizado para «Adriano»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quem_jaz_no_grão_sepulchro,_que_descreve"}]}},
"luis-de-camoes-soneto-quem-pode-livre-ser-gentil-senhora": {"t":["Quem pode livre ser, gentil Senhora,\nVendo-vos com juízo sossegado,\nSe o menino, que de olhos é privado,\nNas meninas dos vossos olhos mora?\n\nAli manda, ali reina, ali namora,\nAli vive das gentes venerado;\nQue o vivo lume, e o rosto delicado,\nImagens são adonde Amor se adora.\n\nQuem vê que em branca neve nascem rosas\nQue crespos fios de ouro vão cercando,\nSe por entre esta luz a vista passa,\n\nRaios de ouro verá, que as duvidosas\nAlmas estão no peito traspassando,\nAssi como um cristal o sol traspassa."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LX, p. 31.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quem_pode_livre_ser,_gentil_Senhora"}]}},
"luis-de-camoes-soneto-como-fizeste-o-porcia-tal-ferida": {"t":["Como fizeste, ó Pórcia, tal ferida?\nFoi voluntária, ou foi por inocência?\nÉ que Amor fazer só quis exp'riência\nSe podia eu sofrer tirar-me a vida.\n\nE com teu próprio sangue te convida\nA que faças à morte resistência?\nÉ que costume faço da paciência,\nPorque o temor morrer me não impida.\n\nPois por que estás comendo fogo ardente,\nSe a ferro te costumas? É que ordena\nAmor que morra, e pene juntamente.\n\nE tens a dor do ferro por pequena?\nSi; que a dor costumada não se sente;\nE não quero eu a morte sem a pena."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXI, p. 31.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nA ed. de 1843 traz «ó Porcia»; «exp'riencia» (elisão escrita) mantida; «porque» interrogativo atualizado para «por que»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Como_fizeste,_ó_Porcia,_tal_ferida%3F"}]}},
"luis-de-camoes-soneto-de-tao-divino-acento-em-voz-humana": {"t":["De tão divino acento em voz humana,\nDe elegâncias que são tão peregrinas,\nSei bem que minhas obras não são dinas;\nQue o rudo engenho meu me desengana.\n\nPorém da vossa pena ilustre mana\nLicor que vence as águas Cabalinas;\nE convosco do Tejo as flores finas\nFarão inveja à cópia Mantuana.\n\nE pois, a vós de si não sendo avaras,\nAs filhas de Mnemosine formosa\nPartes dadas vos têm ao mundo claras;\n\nA minha Musa, e a vossa tão famosa,\nAmbas se podem nele chamar raras,\nA vossa de alta, a minha de invejosa."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXII, p. 32.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNo índice do Wikisource: 'Resposta do Autor a um soneto, pelos mesmos consoantes'.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/De_tão_divino_accento_em_voz_humana"}]}},
"luis-de-camoes-soneto-debaixo-desta-pedra-esta-metido": {"t":["Debaixo desta pedra está metido,\nDas sanguinosas armas descansado,\nO Capitão ilustre e assinalado\nDom Fernando de Castro esclarecido.\n\nEste por todo o Oriente tão temido,\nEste da própria inveja tão cantado,\nEste, enfim, raio de Mavorte irado,\nAqui está agora em terra convertido.\n\nAlegra-te, ó guerreira Lusitânia,\nPor est'outro Viriato que criaste,\nE chora a perda sua eternamente.\n\nExemplo toma nisto de Dardânia;\nQue se a Roma com ele aniquilaste,\nNem por isso Cartago está contente."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXIII, p. 32.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nO Wikisource lista este soneto como «À sepultura de D. Fernando de Castro»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Debaixo_desta_pedra_está_metido"}]}},
"luis-de-camoes-soneto-que-vencais-no-oriente-tantos-reis": {"t":["Que vençais no Oriente tantos Reis,\nQue de novo nos deis da Índia o Estado,\nQue escureçais a fama que hão ganhado\nAqueles, que a ganharam de infiéis;\n\nQue vencidas tenhais da morte as leis,\nE que vencesseis tudo, enfim, armado,\nMais é vencer na pátria, desarmado,\nOs monstros e as Quimeras que venceis.\n\nSobre vencerdes, pois, tanto inimigo,\nE por armas fazer que sem segundo\nNo mundo o vosso nome ouvido seja;\n\nO que vos dá mais fama inda no mundo,\nÉ vencerdes, Senhor, no Reino amigo,\nTantas ingratidões, tão grande inveja."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXIV, p. 33.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\nO Wikisource lista este soneto como «A D. Luís de Ataíde, Viso-Rei»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Que_vençais_no_Oriente_tantos_Reis"}]}},
"luis-de-camoes-soneto-vossos-olhos-senhora-que-competem": {"t":["Vossos olhos, Senhora, que competem\nCom o sol em beleza e claridade,\nEnchem os meus de tal suavidade,\nQue em lágrimas de vê-los se derretem.\n\nMeus sentidos prostrados se submetem\nAssi cegos a tanta majestade;\nE da triste prisão, da escuridade,\nCheios de medo, por fugir, remetem.\n\nPorém se então me vedes por acerto,\nEsse áspero desprezo com que olhais\nMe torna a animar a alma enfraquecida.\n\nOh gentil cura! Oh estranho desconcerto!\nQue dareis co'um favor que vós não dais,\nQuando com um desprezo me dais vida?"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXV, p. 33.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Vossos_olhos,_Senhora,_que_competem"}]}},
"luis-de-camoes-soneto-pois-meus-olhos-nao-cansam-de-chorar": {"t":["Pois meus olhos não cansam de chorar\nTristezas não cansadas de cansar-me;\nPois não se abranda o fogo em que abrasar-me\nPôde quem eu jamais pude abrandar;\n\nNão canse o cego Amor de me guiar\nOnde nunca de lá possa tornar-me;\nNem deixe o mundo todo de escutar-me,\nEnquanto a fraca voz me não deixar.\n\nE se em montes, se em prados, e se em vales\nPiedade mora alguma, algum amor\nEm feras, plantas, aves, pedras, águas;\n\nOuçam a longa história de meus males,\nE curem sua dor com minha dor;\nQue grandes mágoas podem curar mágoas."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXVII, p. 34.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Pois_meus_olhos_n%C3%A3o_cans%C3%A3o_de_chorar"}]}},
"luis-de-camoes-soneto-dai-me-ua-lei-senhora-de-querer-vos": {"t":["Dai-me ũa lei, Senhora, de querer-vos,\nPorque a guarde sob pena de enojar-vos;\nPois a fé que me obriga a tanto amar-vos\nFará que fique em lei de obedecer-vos.\n\nTudo me defendei, senão só ver-vos\nE dentro na minha alma contemplar-vos;\nQue se assi não chegar a contentar-vos,\nAo menos nunca chegue a aborrecer-vos.\n\nE se essa condição cruel e esquiva\nQue me deis lei de vida não consente,\nDai-ma, Senhora, já, seja de morte.\n\nSe nem essa me dais, é bem que viva,\nSem saber como vivo, tristemente;\nMas contente estarei com minha sorte."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXVIII, p. 35.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\n«hũa» atualizado para «ũa» (forma antiga mantida)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Dai-me_hũa_lei,_Senhora,_de_querer-vos"}]}},
"luis-de-camoes-soneto-ferido-sem-ter-cura-perecia": {"t":["Ferido sem ter cura perecia\nO forte e duro Télefo temido\nPor aquele que na água foi metido,\nE a quem ferro nenhum cortar podia.\n\nQuando a Apolíneo Oráculo pedia\nConselho para ser restituído,\nRespondeu-lhe, tornasse a ser ferido\nPor quem o já ferira, e sararia.\n\nAssi, Senhora, quer minha ventura;\nQue ferido de ver-vos claramente,\nCom tornar-vos a ver Amor me cura.\n\nMas é tão doce vossa formosura,\nQue fico como o hidrópico doente,\nQue bebendo lhe cresce mor secura."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXIX, p. 35.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC CDC)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Ferido_sem_ter_cura_perecia"}]}},
"luis-de-camoes-soneto-na-metade-do-ceu-subido-ardia": {"t":["Na metade do céu subido ardia\nO claro, almo Pastor, quando deixavam\nO verde pasto as cabras, e buscavam\nA frescura suave da água fria.\n\nCom a folha das árvores, sombria,\nDo raio ardente as aves se amparavam:\nO módulo cantar, de que cessavam,\nSó nas roucas cigarras se sentia.\n\nQuando Liso pastor n'um campo verde\nNatércia, crua Ninfa, só buscava\nCom mil suspiros tristes que derrama.\n\nPorque te vás de quem por ti se perde,\nPara quem pouco te ama? (suspirava)\nE o eco lhe responde: Pouco te ama."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXX, p. 36.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Na_metade_do_ceo_subido_ardia"}]}},
"luis-de-camoes-soneto-ja-a-roxa-e-branca-aurora-destoucava": {"t":["Já a roxa e branca Aurora destoucava\nOs seus cabelos de ouro delicados,\nE das flores os campos esmaltados\nCom cristalino orvalho borrifava;\n\nQuando o formoso gado se espalhava\nDe Sílvio e de Laurente por os prados;\nPastores ambos, e ambos apartados,\nDe quem o mesmo amor não se apartava.\n\nCom verdadeiras lágrimas Laurente,\nNão sei, (dizia) ó Ninfa delicada,\nPorque não morre já quem vive ausente;\n\nPois a vida sem ti não presta nada.\nResponde Sílvio: Amor não o consente:\nQue ofende as esperanças da tornada."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXI, p. 36.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nA página ligada no Anexo do Wikisource (https://pt.wikisource.org/wiki/J%C3%A1_a_saudosa_Aurora_destoucava) traz texto modernizado sem indicação de edição; aqui segue-se a ed. de 1843.\n\nO Anexo do Wikisource lista este soneto como «Já a saudosa Aurora destoucava» (lição da ed. de 1598, segundo Juromenha); a ed. de 1843 traz «Já a roxa e branca Aurora destoucava»\n\nVariantes na página do Anexo: v. 3 «e as flores nos campos esmaltados»; v. 4 «do cristalino orvalho»; v. 6 «pelos prados»; v. 10 «dezia»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/P%C3%A1gina:Obras_completas_de_Luis_de_Cam%C3%B5es_II_(1843).djvu/110"}]}},
"luis-de-camoes-soneto-quando-de-minhas-magoas-a-comprida": {"t":["Quando de minhas mágoas a comprida\nMaginação os olhos me adormece,\nEm sonhos aquela alma me aparece,\nQue para mi foi sonho nesta vida.\n\nLá n'uma soidade, onde estendida\nA vista por o campo desfalece,\nCorro após ela; e ela então parece\nQue mais de mi se alonga, compelida.\n\nBrado: Não me fujais, sombra benina.\nEla (os olhos em mi co'um brando pejo,\nComo quem diz, que já não pode ser)\n\nTorna a fugir-me: torno a bradar: Dina...\nE antes que diga mene, acordo, e vejo\nQue nem um breve engano posso ter."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXII, p. 37.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quando_de_minhas_mágoas_a_comprida"}]}},
"luis-de-camoes-soneto-suspiros-inflamados-que-cantais": {"t":["Suspiros inflamados que cantais\nA tristeza com que eu vivi tão ledo,\nEu morro e não vos levo, porque hei medo\nQue ao passar do Leteio vos percais.\n\nEscritos para sempre já ficais\nOnde vos mostrarão todos co'o dedo,\nComo exemplo de males; e eu concedo\nQue para aviso de outros estejais.\n\nEm quem, pois, virdes largas esperanças\nDe Amor e da Fortuna, (cujos danos\nAlguns terão por bem-aventuranças)\n\nDizei-lhe, que os servistes muitos anos,\nE que em Fortuna tudo são mudanças,\nE que em Amor não há senão enganos."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXIII, p. 37.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Suspiros_inflammados_que_cantais"}]}},
"luis-de-camoes-soneto-aquela-fera-humana-que-enriquece": {"t":["Aquela fera humana que enriquece\nA sua presunçosa tirania\nDestas minhas entranhas, onde cria\nAmor um mal, que falta quando cresce;\n\nSe nela o Céu mostrou (como parece)\nQuanto mostrar ao mundo pretendia,\nPor que de minha vida se injuria?\nPor que de minha morte se enobrece?\n\nOra, enfim, sublimai vossa vitória,\nSenhora, com vencer-me e cativar-me:\nFazei dela no mundo larga história.\n\nPois, por mais que vos veja atormentar-me,\nJá me fico logrando desta glória\nDe ver que tendes tanta de matar-me."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXIV, p. 38.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\n«crece» atualizado para «cresce»; «Porque» interrogativo atualizado para «Por que»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Aquella_fera_humana_que_enriquece"}]}},
"luis-de-camoes-soneto-ditoso-seja-aquele-que-somente": {"t":["Ditoso seja aquele que somente\nSe queixa de amorosas esquivanças;\nPois por elas não perde as esperanças\nDe poder n'algum tempo ser contente.\n\nDitoso seja quem estando ausente\nNão sente mais que a pena das lembranças;\nPorqu'inda que se tema de mudanças,\nMenos se teme a dor quando se sente.\n\nDitoso seja, enfim, qualquer estado,\nOnde enganos, desprezos e isenção\nTrazem um coração atormentado.\n\nMas triste quem se sente magoado\nDe erros em que não pode haver perdão\nSem ficar na alma a mágoa do pecado"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXV, p. 38.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC CDC)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Ditoso_seja_aquelle_que_somente"}]}},
"luis-de-camoes-soneto-quem-fosse-acompanhando-juntamente": {"t":["Quem fosse acompanhando juntamente\nPor esses verdes campos a avezinha,\nQue despois de perder um bem que tinha,\nNão sabe mais que cousa é ser contente!\n\nE quem fosse apartando-se da gente.\nEla por companheira e por vizinha,\nMe ajudasse a chorar a pena minha,\nE eu a ela também a que ela sente!\n\nDitosa ave! que ao menos, se a natura\nA seu primeiro bem não dá segundo,\nDá-lhe o ser triste a seu contentamento.\n\nMas triste quem de longe quis ventura\nQue para respirar lhe falte o vento,\nE para tudo, enfim, lhe falte o mundo!"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXVI, p. 39.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CED)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quem_fosse_acompanhando_juntamente"}]}},
"luis-de-camoes-soneto-o-culto-divinal-se-celebrava": {"t":["O culto divinal se celebrava\nNo templo donde toda criatura\nLouva o Feitor divino, que a feitura\nCom seu sagrado sangue restaurava.\n\nAmor ali, que o tempo me aguardava\nOnde a vontade tinha mais segura,\nCom uma rara e angélica figura\nA vista da razão me salteava.\n\nEu crendo que o lugar me defendia\nDe seu livre costume, não sabendo\nQue nenhum confiado lhe fugia;\n\nDeixei-me cativar: mas hoje vendo,\nSenhora, que por vosso me queria,\nDo tempo que fui livre me arrependo."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXVII, p. 39.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/O_culto_divinal_se_celebrava"}]}},
"luis-de-camoes-soneto-leda-serenidade-deleitosa": {"t":["Leda serenidade deleitosa,\nQue representa em terra um paraíso;\nEntre rubis e perlas doce riso,\nDebaixo de ouro e neve cor de rosa;\n\nPresença moderada e graciosa,\nOnde ensinando estão despejo e siso\nQue se pode por arte e por aviso,\nComo por natureza, ser formosa;\n\nFala de que ou já vida, ou morte pende.\nRara e suave, enfim, Senhora, vossa,\nRepouso na alegria comedido;\n\nEstas as armas são com que me rende\nE me cativa Amor; mas não que possa\nDespojar-me da glória de rendido."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXVIII, p. 40.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Leda_serenidade_deleitosa"}]}},
"luis-de-camoes-soneto-bem-sei-amor-que-e-certo-o-que-receio": {"t":["Bem sei, Amor, que é certo o que receio;\nMas tu, porque com isso mais te apuras,\nDe manhoso mo negas, e mo juras\nNesse teu arco de ouro; e eu te creio.\n\nA mão tenho metida no meu seio,\nE não vejo os meus danos às escuras:\nPorém porfias tanto e me asseguras,\nQue me digo que minto, e que me enleio.\n\nNem somente consinto neste engano,\nMas inda to agradeço, e a mi me nego\nTudo o que vejo e sinto de meu dano.\n\nOh poderoso mal a que me entrego!\nQue no meio do justo desengano\nMe possa inda cegar um moço cego?"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXIX, p. 40.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Bem_sei,_Amor,_que_he_certo_o_que_receio"}]}},
"luis-de-camoes-soneto-como-quando-do-mar-tempestuoso": {"t":["Como quando do mar tempestuoso\nO marinheiro todo trabalhado,\nDe um naufrágio cruel saindo a nado,\nSó de ouvir falar nele está medroso:\n\nFirme jura que o vê-lo bonançoso\nDo seu lar o não tire sossegado;\nMas esquecido já do horror passado,\nDele a fiar se torna cobiçoso:\n\nAssi, Senhora, eu que da tormenta\nDe vossa vista fujo, por salvar-me,\nJurando de não mais em outra ver-me;\n\nCom a alma que de vós nunca se ausenta,\nMe torno, por cobiça de ganhar-me,\nOnde estive tão perto de perder-me."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXX, p. 41.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Como_quando_do_mar_tempestuoso"}]}},
"luis-de-camoes-soneto-amor-e-um-fogo-que-arde-sem-se-ver": {"t":["Amor é um fogo que arde sem se ver;\nÉ ferida que dói e não se sente;\nÉ um contentamento descontente;\nÉ dor que desatina sem doer;\n\nÉ um não querer mais que bem querer;\nÉ solitário andar por entre a gente;\nÉ um não contentar-se de contente;\nÉ cuidar que se ganha em se perder;\n\nÉ um estar-se preso por vontade;\nÉ servir a quem vence o vencedor;\nÉ um ter com quem nos mata lealdade.\n\nMas como causar pode o seu favor\nNos mortais corações conformidade,\nSendo a si tão contrário o mesmo Amor?"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXXI, p. 41.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Amor_he_hum_fogo_que_arde_sem_se_ver"}]}},
"luis-de-camoes-soneto-se-pena-por-amar-vos-se-merece": {"t":["Se pena por amar-vos se merece,\nQuem dela estará livre? quem isento?\nE que alma, que razão, que entendimento\nNo instante em que vos vê não obedece?\n\nQual mor glória na vida já se ofrece,\nQue a de ocupar-se em vós o pensamento?\nNão só todo rigor, todo tormento\nCom ver-vos não magoa, mas se esquece.\n\nPorém se heis de matar a quem amando,\nSer vosso de amor tanto só pretende,\nO mundo matareis, que todo é vosso.\n\nEm mi podeis, Senhora, ir começando,\nPois bem claro se mostra e bem se entende\nAmar-vos quanto devo e quanto posso."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXXII, p. 42.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\n'ofrece' (v5; fonte: 'offrece'), forma sincopada de 'oferece', trissílaba; mantida.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Se_pena_por_amar-vos_se_merece"}]}},
"luis-de-camoes-soneto-que-levas-cruel-morte-um-claro-dia": {"t":["Que levas, cruel Morte? Um claro dia.\nA que horas o tomaste? Amanhecendo.\nE entendes o que levas? Não o entendo.\nPois quem to faz levar? Quem o entendia.\n\nSeu corpo quem o goza? A terra fria.\nComo ficou sua luz? Anoitecendo.\nLusitânia que diz? Fica dizendo...\nQue diz? Não mereci a grã Maria.\n\nMataste a quem a viu? Já morto estava.\nQue discorre o Amor? Falar não ousa.\nE quem o faz calar? Minha vontade.\n\nNa Corte que ficou? Saudade brava.\nQue fica lá que ver? Nenhuma cousa.\nQue glória lhe faltou? Esta beldade"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXXIII, p. 42.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto dialogado (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Que_levas,_cruel_Morte%3F_Hum_claro_dia"}]}},
"luis-de-camoes-soneto-ondados-fios-de-ouro-reluzente": {"t":["Ondados fios de ouro reluzente,\nQue agora da mão bela recolhidos,\nAgora sobre as rosas esparzidos\nFazeis que a sua graça se acrescente;\n\nOlhos, que vos moveis tão docemente,\nEm mil divinos raios incendidos,\nSe de cá me levais a alma e sentidos,\nQue fora, se eu de vós não fora ausente?\n\nHonesto riso, que entre a mor fineza\nDe perlas e corais nasce e aparece;\nOh quem seus doces ecos já lhe ouvisse!\n\nSe imaginando só tanta beleza,\nDe si com nova glória a alma se esquece,\nQue será quando a vir? Ah quem a visse!"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXXIV, p. 43.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Ondados_fios_de_ouro_reluzente"}]}},
"luis-de-camoes-soneto-foi-ja-n-um-tempo-doce-cousa-amar": {"t":["Foi já n'um tempo doce cousa amar,\nEnquanto me enganou uma esperança:\nO coração com esta confiança\nTodo se desfazia em desejar.\n\nOh vão, caduco e débil esperar!\nComo, enfim, desengana uma mudança!\nQue quanto é mor a bem-aventurança,\nTanto menos se crê que há de durar.\n\nQuem já se viu com gostos prosperado,\nVendo-se brevemente em pena tanta,\nRazão tem de viver bem magoado.\n\nMas quem já tem o mundo exprimentado,\nNão o magoa a pena, nem o espanta;\nQue mal se estranhara o costumado."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXXV, p. 43.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC CDC)\n\n**Notas sobre o texto.**\n\nO Anexo do Wikisource dá o 1.º verso como «Foi já um tempo doce cousa amar»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Foi_ja_n'hum_tempo_doce_cousa_amar"}]}},
"luis-de-camoes-soneto-dos-antigos-ilustres-que-deixaram": {"t":["Dos antigos Ilustres, que deixaram\nUm nome digno de imortal memória,\nFicou por luz do tempo a larga história\nDos feitos em que mais se avantajaram.\n\nSe com suas ações se cotejaram\nMil vossas, cada uma tão notória,\nVencera a menor delas a mor glória\nQue eles em tantos anos alcançaram.\n\nA glória sua foi: ninguém lha tome:\nSeguindo cada qual vários caminhos\nEstátuas mereceu no heroico Templo.\n\nVós honra Portuguesa e dos Coutinhos,\nClaríssimo Dom João, com melhor nome\nA vós encheis de glória, a nós de exemplo."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXXVI, p. 44.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\nOutras edições: «Dos ilustres antigos que deixaram»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Dos_antigos_Illustres,_que_deixárão"}]}},
"luis-de-camoes-soneto-conversacao-domestica-afeicoa": {"t":["Conversação doméstica afeiçoa,\nOra em forma de limpa e sãa vontade,\nOra de uma amorosa piedade,\nSem olhar qualidade de pessoa.\n\nSe despois, porventura, vos magoa\nCom desamor e pouca lealdade,\nLogo vos faz mentira da verdade\nO brando Amor, que tudo, enfim, perdoa,\n\nNão são isto que falo conjecturas\nQue o pensamento julga na aparência,\nPor fazer delicadas escrituras.\n\nMetida tenho a mão na consciência,\nE não falo senão verdades puras\nQue me ensinou a viva experiência."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXXVII, p. 44.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\n«sãa» (= sã) mantido.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Conversação_doméstica_affeiçoa"}]}},
"luis-de-camoes-soneto-esforco-grande-igual-ao-pensamento": {"t":["Esforço grande, igual ao pensamento,\nPensamentos em obras divulgados,\nE não em peito tímido encerrados,\nE desfeitos despois em chuva e vento;\n\nÂnimo da cobiça baixa isento,\nDigno por isto só de altos estados,\nFero açoute dos nunca bem domados\nPovos do Malabar sanguinolento;\n\nGentileza de membros corporais\nOrnados de pudica continência,\nObra por certo da celeste altura:\n\nEstas virtudes raras e outras mais,\nDignas todas da Homérica eloquência,\nJazem debaixo desta sepultura."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXXVIII, p. 45.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Esf%C3%B4r%C3%A7o_grande,_igual_ao_pensamento"}]}},
"luis-de-camoes-soneto-no-mundo-quis-o-tempo-que-se-achasse": {"t":["No mundo quis o Tempo que se achasse\nO bem que por acerto, ou sorte vinha;\nE por exprimentar que dita tinha,\nQuis que a Fortuna em mi se exprimentasse.\n\nMas porque o meu destino me mostrasse\nQue nem ter esperanças me convinha,\nNunca nesta tão longa vida minha\nCousa me deixou ver que desejasse.\n\nMudando andei costume, terra, estado,\nPor ver se se mudava a sorte dura;\nA vida pus nas mãos de um leve lenho.\n\nMas, segundo o que o Céu me tem mostrado,\nJá sei que deste meu buscar ventura\nAchado tenho já que não a tenho."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, LXXXIX, p. 45.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nO Anexo do Wikisource dá o 1.º verso como «No mundo quis um tempo que se achasse»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/No_mundo_quiz_o_Tempo_que_se_achasse"}]}},
"luis-de-camoes-soneto-vos-que-de-olhos-suaves-e-serenos": {"t":["Vós, que de olhos suaves e serenos,\nCom justa causa a vida cativais,\nE que os outros cuidados condenais\nPor indevidos, baixos e pequenos;\n\nSe de Amor os domésticos venenos\nNunca provastes, quero que sintais\nQue é tanto mais o amor despois que amais,\nQuanto são mais as causas de ser menos.\n\nE não presuma alguém que algum defeito,\nQuando na cousa amada se apresenta,\nPossa diminuir o amor perfeito:\n\nAntes o dobra mais; e se atormenta,\nPouco a pouco desculpa o brando peito;\nQue Amor com seus contrários se acrescenta."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XCI, p. 46.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Vós,_que_de_olhos_suaves_e_serenos"}]}},
"luis-de-camoes-soneto-que-poderei-do-mundo-ja-querer": {"t":["Que poderei do mundo já querer,\nPois no mesmo em que pus tamanho amor,\nNão vi senão desgosto e desfavor,\nE morte, enfim; que mais não pode ser?\n\nPois me não farta a vida de viver,\nPois já sei que não mata grande dor,\nSe houver cousa que mágoa dê maior,\nEu a verei; que tudo posso ver.\n\nA Morte, a meu pesar, me assegurou\nDe quanto mal me vinha: já perdi\nO que a perder o medo me ensinou.\n\nNa vida desamor somente vi,\nNa morte a grande dor que me ficou:\nParece que para isto só nasci."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XCII, p. 47.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Que_poderei_do_mundo_ja_querer"}]}},
"luis-de-camoes-soneto-pensamentos-que-agora-novamente": {"t":["Pensamentos, que agora novamente\nCuidados vãos em mi ressuscitais,\nDizei-me: E ainda não vos contentais\nDe ter a quem vos tem tão descontente?\n\nQue fantasia é esta, que presente\nCad'hora ante os meus olhos me mostrais?\nCom uns sonhos tão vãos inda tentais\nQuem nem por sonhos pode ser contente?\n\nVejo-vos, pensamentos, alterados,\nE não quereis, de esquivos, declarar-me\nQue é isto que vos traz tão enleados?\n\nNão mo negueis, se andais para negar-me;\nPorque se contra mi 'stais levantados,\nEu vos ajudarei mesmo a matar-me."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XCIII, p. 47.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Pensamentos,_que_agora_novamente"}]}},
"luis-de-camoes-soneto-se-tomo-a-minha-pena-em-penitencia": {"t":["Se tomo a minha pena em penitência\nDo error em que caiu o pensamento,\nNão abrando, mas dobro meu tormento,\nQue a tanto, e mais, obriga a paciência.\n\nE se uma cor de morto na aparência,\nUm espalhar suspiros vãos ao vento\nNão faz em vós, Senhora, movimento,\nFique o meu mal em vossa consciência.\n\nMas se de qualquer áspera mudança\nToda vontade isenta Amor castiga,\n(Como eu vejo no mal que me condena)\n\nE se em vós não se entende haver vingança,\nSerá forçado (pois Amor me obriga)\nQue eu só da culpa vossa pague a pena."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XCIV, p. 48.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nO índice do Wikisource dá o primeiro verso como 'Se tomar minha pena em penitência' (outra lição)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Se_tomo_a_minha_pena_em_penitencia"}]}},
"luis-de-camoes-soneto-aquela-que-de-pura-castidade": {"t":["Aquela que, de pura castidade,\nDe si mesma tomou cruel vingança\nPor uma breve e súbita mudança\nContrária à sua honra e qualidade;\n\nVenceu à formosura a honestidade,\nVenceu no fim da vida a esperança,\nPorque ficasse viva tal lembrança,\nTal amor, tanta fé, tanta verdade.\n\nDe si, da gente e do mundo esquecida,\nFeriu com duro ferro o brando peito,\nBanhando em sangue a força do tirano.\n\nOh ousadia estranha! estranho feito!\nQue dando breve morte ao corpo humano,\nTenha sua memória larga vida!"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XCV, p. 48.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DEC)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Aquella_que,_de_pura_castidade"}]}},
"luis-de-camoes-soneto-os-vestidos-elisa-revolvia": {"t":["Os vestidos Elisa revolvia,\nQue Eneias lhe deixara por memória;\nDoces despojos da passada glória;\nDoces quando seu fado o consentia.\n\nEntre eles a formosa espada via,\nQue instrumento, enfim, foi da triste história;\nE como quem de si tinha a vitória,\nFalando só com ela, assi dizia:\n\nFormosa e nova espada, se ficaste\nSó porque executasses os enganos\nDe quem te quis deixar, em minha vida;\n\nSabe que tu comigo te enganaste;\nQue para me tirar de tantos danos\nSobeja-me a tristeza da partida."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XCVI, p. 49.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Os_vestidos_Elisa_revolvia"}]}},
"luis-de-camoes-soneto-oh-quao-caro-me-custa-o-entender-te": {"t":["Oh quão caro me custa o entender-te,\nMolesto Amor que, só por alcançar-te,\nDe dor em dor me tens trazido a parte\nDonde em ti ódio e ira se converte!\n\nCuidei que para em tudo conhecer-te\nMe não faltava experiência e arte;\nMas na alma vejo agora acrescentar-te\nAquilo que era causa de perder-te.\n\nEstavas tão secreto no meu peito,\nQue eu mesmo, que te tinha, não sabia\nQue me senhoreavas deste jeito.\n\nDescubriste-te agora; e foi por via\nQue teu descobrimento e meu defeito,\nUm me envergonha e outro me injuria."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XCVII, p. 49.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Oh_qu%C3%A3o_caro_me_custa_o_entender-te"}]}},
"luis-de-camoes-soneto-se-despois-de-esperanca-tao-perdida": {"t":["Se despois de esperança tão perdida,\nAmor por causa alguma consentisse\nQue inda algum'hora breve alegre visse\nDe quantas tristes viu tão longa vida;\n\nUm'alma já tão fraca e tão caída\n(Quando a sorte mais alto me subisse)\nNão tenho para mi que consentisse\nAlegria tão tarde consentida.\n\nNem tão somente o Amor me não mostrou\nUm'hora em que vivesse alegremente,\nDe quantas nesta vida me negou;\n\nMas inda tanta pena me consente,\nQue co'o contentamento me tirou\nO gosto de algum'hora ser contente."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XCVIII, p. 50.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Se_despois_de_esperança_tão_perdida"}]}},
"luis-de-camoes-soneto-o-raio-cristalino-se-estendia": {"t":["O raio cristalino se estendia\nPor o mundo da Aurora marchetada,\nQuando Nise, pastora delicada,\nDonde a vida deixava se partia.\n\nDos olhos, com que o sol escurecia,\nLevando a luz em lágrimas banhada,\nDe si, do fado, e tempo magoada,\nPondo os olhos no Céu, assi dizia:\n\nNasce, sereno sol, puro e luzente;\nResplandece, purpúrea e branca aurora,\nQualquer alma alegrando descontente;\n\nQue a minha, sabe tu que desde agora\nJamais na vida a podes ver contente,\nNem tão triste nenhuma outra pastora."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, XCIX, p. 50.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/O_raio_crystallino_se_estendia"}]}},
"luis-de-camoes-soneto-no-mundo-poucos-anos-e-cansados": {"t":["No mundo poucos anos e cansados\nVivi, cheios de vil miséria e dura:\nFoi-me tão cedo a luz do dia escura,\nQue não vi cinco lustros acabados.\n\nCorri terras e mares apartados,\nBuscando à vida algum remédio ou cura:\nMas aquilo que, enfim, não dá ventura\nNão o dão os trabalhos arriscados.\n\nCriou-me Portugal na verde e cara\nPátria minha Alenquer; mas ar corruto,\nQue neste meu terreno vaso tinha,\n\nMe fez manjar de peixes em ti, bruto\nMar, que bates a Abássia fera e avara,\nTão longe da ditosa pátria minha."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, C, p. 51.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\n«chara» (fonte, latinismo gráfico) = cara (v. 9)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/No_mundo_poucos_annos_e_cansados"}]}},
"luis-de-camoes-soneto-quem-pudera-julgar-de-vos-senhora": {"t":["Quem pudera julgar de vós, Senhora,\nQue uma tal fé pudesse assi perder-vos?\nSe por amar-vos chego a aborrecer-vos,\nDeixar não posso o amar-vos algum'hora.\n\nDeixais a quem vos ama, ou vos adora,\nPor ver a quem quiçá não sabe ver-vos?\nMas eu sou quem não soube merecer-vos,\nE esta minha ignorância entendo agora.\n\nNunca soube entender vossa vontade,\nNem a minha mostrar-vos verdadeira,\nInda que clara estava esta verdade.\n\nEsta, enquanto eu viver, vereis inteira;\nE se em vão meu querer vos persuade,\nMais vosso não querer faz que vos queira."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CV, p. 53.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nSoneto ausente dos 166 sonetos do texto-base de Costa Pimpão (Biblioteca Virtual do Estudante Brasileiro, USP); atribuição possivelmente duvidosa.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quem_pudéra_julgar_de_vós,_Senhora"}]}},
"luis-de-camoes-soneto-quem-senhora-presume-de-louvar-vos": {"t":["Quem, Senhora, presume de louvar-vos\nCom discurso que baixe de divino,\nDe tanto maior pena será dino,\nQuanto vós sois maior ao contemplar-vos.\n\nNão aspire algum canto a celebrar-vos,\nPor mais que seja raro, ou peregrino;\nPois de vossa beleza eu imagino\nQue só convosco o Céu quis comparar-vos.\n\nDitosa esta alma vossa, a que quisestes\nPôr em posse de prenda tão subida,\nQual esta que benigna, enfim, me destes.\n\nSempre será anteposta à mesma vida:\nEsta estimar em menos me fizestes,\nSe antes que ess'outra a quero ver perdida."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CVI, p. 54.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nO índice do Wikisource dá o primeiro verso como 'Quem presumir, Senhora, de louvar-vos' (outra lição); a ed. de 1843 traz 'Quem, Senhora, presume de louvar-vos'.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quem,_Senhora,_presume_de_louvar-vos"}]}},
"luis-de-camoes-soneto-moradoras-gentis-e-delicadas": {"t":["Moradoras gentis e delicadas\nDo claro e áureo Tejo, que metidas\nEstais em suas grutas escondidas,\nE com doce repouso sossegadas;\n\nAgora esteis de amores inflamadas,\nNos cristalinos paços entretidas;\nAgora no exercício embevecidas\nDas telas de ouro puro matizadas;\n\nMovei dos lindos rostos a luz pura\nDe vossos olhos belos, consentindo\nQue lágrimas derramem de tristura.\n\nE assi com dor mais própria ireis ouvindo\nAs queixas que derramo da Ventura,\nQue com penas de Amor me vai seguindo."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CVII, p. 54.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Moradoras_gentis_e_delicadas"}]}},
"luis-de-camoes-soneto-ja-claro-vejo-bem-ja-bem-conheco": {"t":["Já claro vejo bem, já bem conheço\nQuanto aumentando vou o meu tormento;\nPois sei que fundo em água, escrevo em vento,\nE que o cordeiro manso ao lobo peço;\n\nQue Aracne sou, pois já com Palas teço;\nQue a tigres em meus males me lamento;\nQue reduzir o mar a um vaso intento,\nAspirando a esse céu que não mereço.\n\nQuero achar paz em um confuso inferno;\nNa noite do sol puro a claridade;\nE o suave verão no duro inverno.\n\nBusco em luzente Olimpo escuridade,\nE o desejado bem no mal eterno,\nBuscando amor em vossa crueldade."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXV, p. 58.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Ja_claro_vejo_bem,_ja_bem_conhe%C3%A7o"}]}},
"luis-de-camoes-soneto-nao-vas-ao-monte-nise-com-teu-gado": {"t":["Não vás ao monte, Nise, com teu gado;\nQue lá vi que Cupido te buscava:\nPor ti somente a todos perguntava,\nNo gesto menos plácido que irado.\n\nEle publica, enfim, que lhe hás roubado\nOs melhores farpões da sua aljava;\nE com um dardo ardente assegurava\nTraspassar esse peito delicado.\n\nFuge de ver-te lá nesta aventura,\nPorque se contra ti o tens iroso,\nPode ser que te alcance com mão dura.\n\nMas ai! que em vão te advirto temeroso,\nSe à tua incomparável formosura\nSe rende o dardo seu mais poderoso!"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXVIII, p. 60.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/N%C3%A3o_v%C3%A1s_ao_monte,_Nise,_com_teu_gado"}]}},
"luis-de-camoes-soneto-a-violeta-mais-bela-que-amanhece": {"t":["A violeta mais bela que amanhece\nNo vale por esmalte da verdura,\nCom seu pálido lustre e formosura,\nPor mais bela, Violante, te obedece.\n\nPerguntas-me por quê? Porque aparece\nEm ti seu nome, e sua cor mais pura;\nE estudar em teu rosto só procura\nTudo quanto em beldade mais floresce.\n\nOh luminosa flor! Oh sol mais claro!\nÚnico roubador de meu sentido,\nNão permitas que Amor me seja avaro.\n\nOh penetrante seta de Cupido!\nQue queres? Que te peça por reparo\nSer neste vale Eneias desta Dido?"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXIX, p. 60.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\n«florece» atualizado para «floresce»; «porque?» interrogativo final atualizado para «por quê?»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/A_violeta_mais_bella_que_amanhece"}]}},
"luis-de-camoes-soneto-tornai-essa-brancura-a-alva-acucena": {"t":["Tornai essa brancura à alva açucena,\nE essa purpúrea cor às puras rosas;\nTornai ao sol as chamas luminosas\nDe essa vista que a roubos vos condena.\n\nTornai à suavíssima sirena\nD'essa voz as cadências deleitosas:\nTornai a graça às Graças, que queixosas\nEstão de a ter por vós menos serena:\n\nTornai à bela Vênus a beleza;\nA Minerva o saber, o engenho, e a arte;\nE a pureza à castíssima Diana.\n\nDespojai-vos de toda essa grandeza\nDe dões; e ficareis em toda parte\nConvosco só, que é só ser inumana."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXX, p. 61.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nSoneto ausente dos 166 sonetos do texto-base de Costa Pimpão (Biblioteca Virtual do Estudante Brasileiro, USP); atribuição possivelmente duvidosa.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Tornae_essa_brancura_á_alva_assucena"}]}},
"luis-de-camoes-soneto-a-chaga-que-senhora-me-fizestes": {"t":["A chaga que, Senhora, me fizestes,\nNão foi para curar-se em um só dia;\nPorque crescendo vai com tal porfia,\nQue bem descobre o intento que tivestes.\n\nDe causar tanta dor vos não doestes?\nMas a doer-vos, dor me não seria,\nPois já com esperança me veria\nDo que vós que em mi visse não quisestes.\n\nOs olhos com que todo me roubastes\nForam causa do mal que vou passando;\nE vós estais fingindo o não causastes.\n\nMas eu me vingarei. E sabeis quando?\nQuando vos vir queixar porque deixastes\nIr-se a minha alma neles abrasando."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXXIII, p. 62.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/A_chaga_que,_Senhora,_me_fizestes"}]}},
"luis-de-camoes-soneto-se-com-desprezos-ninfa-te-parece": {"t":["Se com desprezos, Ninfa, te parece\nQue podes desviar do seu cuidado\nUm coração constante, que se ofrece\nA ter por glória o ser atormentado.\n\nDeixa a tua porfia, e reconhece\nQue mal sabes de amor desenganado;\nPois não sentes, nem vês que em teu mal cresce,\nCrescendo em mi de ti mais desamado.\n\nO esquivo desamor, com que me tratas,\nConverte em piedade, se não queres\nQue cresça o meu querer, e o teu desgosto.\n\nVencer-me com cruezas nunca esperes:\nBem me podes matar, e bem me matas;\nMas sempre há de viver meu pressuposto."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXXIV, p. 63.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABAB ABAB CDE DCE)\n\n**Notas sobre o texto.**\n\n'ofrece' (v3; fonte: 'offrece'), forma sincopada de 'oferece', trissílaba; mantida.\n\nSoneto ausente dos 166 sonetos do texto-base de Costa Pimpão (Biblioteca Virtual do Estudante Brasileiro, USP); atribuição possivelmente duvidosa.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Se_com_desprezos,_Nympha,_te_parece"}]}},
"luis-de-camoes-soneto-uma-admiravel-erva-se-conhece": {"t":["Uma admirável erva se conhece,\nQue vai ao sol seguindo de hora em hora,\nLogo que ele do Eufrates se vê fora,\nE quando está mais alto, então floresce.\n\nMas quando ao Oceano o carro desce,\nToda a sua beleza perde Flora,\nPorque ela se emurchece e se descora:\nTanto co'a luz ausente se entristece!\n\nMeu sol, quando alegrais esta alma vossa,\nMostrando-lhe esse rosto que dá vida,\nCria flores em seu contentamento.\n\nMas logo, em não vos vendo, entristecida\nSe murcha e se consume em grão tormento:\nNem há quem vossa ausência sofrer possa."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXXVIII, p. 65.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DEC)\n\n**Notas sobre o texto.**\n\nSoneto ausente dos 166 sonetos do texto-base de Costa Pimpão (Biblioteca Virtual do Estudante Brasileiro, USP); atribuição possivelmente duvidosa.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Huma_admiravel_herva_se_conhece"}]}},
"luis-de-camoes-soneto-crescei-desejo-meu-pois-que-a-ventura": {"t":["Crescei, desejo meu, pois que a Ventura\nJá vos tem nos seus braços levantado;\nQue a bela causa de que sois gerado\nO mais ditoso fim vos assegura.\n\nSe aspirais por ousado a tanta altura,\nNão vos espante haver ao sol chegado;\nPorque é de águia Real vosso cuidado,\nQue quanto mais o sofre, mais se apura.\n\nÂnimo, coração; que o pensamento\nTe pode inda fazer mais glorioso,\nSem que respeite a teu merecimento.\n\nQue cresças inda mais é já forçoso;\nPorque se foi de ousado o teu intento,\nAgora de atrevido é venturoso."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXXIX, p. 65.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nOutras edições: «Crecei, desejo meu»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Crescei,_desejo_meu,_pois_que_a_Ventura"}]}},
"luis-de-camoes-soneto-de-quantas-gracas-tinha-a-natureza": {"t":["De quantas graças tinha a natureza\nFez um belo e riquíssimo tesouro;\nE com rubis e rosas, neve e ouro,\nFormou sublime e angélica beleza.\n\nPôs na boca os rubis, e na pureza\nDo belo rosto as rosas, por quem mouro;\nNo cabelo o valor do metal louro;\nNo peito a neve, em que a alma tenho acesa.\n\nMas nos olhos mostrou quanto podia,\nE fez deles um sol, onde se apura\nA luz mais clara que a do claro dia.\n\nEnfim, Senhora, em vossa compostura,\nEla a apurar chegou quanto sabia\nDe ouro, rosas, rubis, neve e luz pura."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXXXI, p. 66.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/De_quantas_graças_tinha_a_natureza"}]}},
"luis-de-camoes-soneto-doces-e-claras-aguas-do-mondego": {"t":["Doces e claras águas do Mondego,\nDoce repouso de minha lembrança,\nOnde a comprida e pérfida esperança\nLongo tempo após si me trouxe cego,\n\nDe vós me aparto, si; porém não nego\nQue inda a longa memória, que me alcança,\nMe não deixa de vós fazer mudança,\nMas quanto mais me alongo, mais me achego\n\nBem poderá a Fortuna este instrumento\nDa alma levar por terra nova e estranha,\nOferecido ao mar remoto, ao vento.\n\nMas a alma, que de cá vos acompanha,\nNas asas do ligeiro pensamento\nPara vós, águas, voa, e em vós se banha."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXXXIII, p. 67.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nOutras edições: «Doces águas e claras do Mondego»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Doces_e_claras_águas_do_Mondego"}]}},
"luis-de-camoes-soneto-senhor-joao-lopes-o-meu-baixo-estado": {"t":["Senhor João Lopes, o meu baixo estado\nOntem vi posto em grau tão excelente,\nQue sendo vós inveja a toda a gente,\nSó por mi vos quisereis ver trocado.\n\nO gesto vi suave e delicado,\nQue já vos fez contente e descontente,\nLançar ao vento a voz tão docemente,\nQue fez o ar sereno e sossegado.\n\nVi-lhe em poucas palavras dizer quanto\nNinguém diria em muitas: mas eu chego\nA espirar só de ouvir a doce fala.\n\nOh mal o haja a Fortuna, e o moço cego!\nEle, que os corações obriga a tanto;\nEla, porque os estados desiguala."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXXXIV, p. 68.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\n'espirar' (v11) mantido como na fonte (= expirar)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Senhor_João_Lopes,_o_meu_baixo_estado"}]}},
"luis-de-camoes-soneto-a-morte-que-da-vida-o-no-desata": {"t":["A Morte, que da vida o nó desata,\nOs nós, que dá o Amor, cortar quisera\nCo'a ausência, que é sobre ele espada fera,\nE co'o tempo, que tudo desbarata.\n\nDuas contrárias, que uma a outra mata,\nA Morte contra Amor junta e altera;\nUma, Razão contra a Fortuna austera;\nOutra, contra a Razão Fortuna ingrata.\n\nMas mostre a sua imperial potência\nA Morte em apartar de um corpo a alma,\nO Amor n'um corpo duas almas una;\n\nPara que assi triunfante leve a palma\nDa Morte Amor a grão pesar da ausência,\nDo tempo, da Razão, e da Fortuna."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXXXV, p. 68.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/A_Morte,_que_da_vida_o_nó_desata"}]}},
"luis-de-camoes-soneto-o-filho-de-latona-esclarecido": {"t":["O filho de Latona esclarecido,\nQue com seu raio alegra a humana gente,\nMatar pôde a Pitônica serpente\nQue mortes mil havia produzido.\n\nFeriu com arco, e de arco foi ferido,\nCom ponta aguda de ouro reluzente:\nNas Tessálicas praias docemente\nPor a ninfa Peneia andou perdido.\n\nNão lhe pôde valer contra seu dano\nSaber, nem diligências, nem respeito\nDe quanto era celeste e soberano.\n\nPois se um deus nunca viu nem um engano\nDe quem era tão pouco em seu respeito,\nEu qu'espero de um ser, qu'é mais que humano?"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXXXVII, p. 69.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC CDC)\n\n**Notas sobre o texto.**\n\n«Phytonica» (fonte) = Pitônica (de Píton), v. 3.\n\n«deos» no v. 12 = um deus (Apolo), com minúscula como na fonte.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/O_filho_de_Latona_esclarecido"}]}},
"luis-de-camoes-soneto-presenca-bela-angelica-figura": {"t":["Presença bela, angélica figura,\nEm quem quanto o Céu tinha nos tem dado;\nGesto alegre de rosas semeado,\nEntre as quais se está rindo a Formosura:\n\nOlhos, onde tem feito tal mistura\nEm cristal puro o negro marchetado,\nQue vemos já no verde delicado\nNão esperança, mas inveja escura:\n\nBrandura, aviso, e graça, que aumentando\nA natural beleza co'um desprezo,\nCom que mais desprezada mais se aumenta:\n\nSão as prisões de um coração, que preso,\nSeu mal ao som dos ferros vai cantando,\nComo faz a sereia na tormenta."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXXXVIII, p. 70.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Presença_bella,_angelica_figura"}]}},
"luis-de-camoes-soneto-por-cima-destas-aguas-forte-e-firme": {"t":["Por cima destas águas forte e firme\nIrei aonde os Fados o ordenaram,\nPois por cima de quantas derramaram\nAqueles claros olhos pude vir-me.\n\nJá chegado era o fim de despedir-me;\nJá mil impedimentos se acabaram,\nQuando rios de amor se atravessaram\nA me impedir o passo de partir-me.\n\nPassei-os eu com ânimo obstinado,\nCom que a morte forçada gloriosa\nFaz o vencido já desesperado.\n\nEm qual figura, ou gesto desusado,\nPode já fazer medo a morte irosa\nA quem tem a seus pés rendido e atado?"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXXXIX, p. 70.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC CDC)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Por_cima_destas_%C3%A1guas_forte_e_firme"}]}},
"luis-de-camoes-soneto-tal-mostra-de-si-da-vossa-figura": {"t":["Tal mostra de si dá vossa figura,\nSibela, clara luz da redondeza,\nQue as forças e o poder da natureza\nCom sua claridade mais apura.\n\nQuem confiança há visto tão segura,\nTão singular esmalte da beleza,\nQue não padeça mal de mais graveza,\nSe resistir a seu amor procura?\n\nEu, pois, por escusar tal esquivança,\nA razão sujeitei ao pensamento,\nA quem logo os sentidos se entregaram.\n\nSe vos ofende o meu atrevimento,\nInda podeis tomar nova vingança\nNas relíquias da vida que ficaram."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXL, p. 71.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\nO índice do Wikisource dá o primeiro verso como 'Tal mostra dá de si vossa figura' (outra ordem)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Tal_mostra_de_si_dá_vossa_figura"}]}},
"luis-de-camoes-soneto-na-desesperacao-ja-repousava": {"t":["Na desesperação já repousava\nO peito longamente magoado,\nE, com seu dano eterno concertado,\nJá não temia, já não desejava;\n\nQuando uma sombra vã me assegurava\nQue algum bem me podia estar guardado\nEm tão formosa imagem, que o traslado\nN'alma ficou, que nela se enlevava.\n\nQue crédito que dá tão facilmente\nO coração àquilo que deseja,\nQuando lhe esquece o fero seu destino!\n\nAh! deixem-me enganar; que eu sou contente;\nPois, posto que maior meu dano seja,\nFica-me a glória já do que imagino."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXLI, p. 71.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nPonto final do v. 14 restituído conforme o Gutenberg n.º 31509 (falta na transcrição do Wikisource)\n\n«vãa» (fonte) = vã (v. 5)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Na_desespera%C3%A7%C3%A3o_ja_repousava"}]}},
"luis-de-camoes-soneto-diversos-does-reparte-o-ceu-benino": {"t":["Diversos dões reparte o Céu benino,\nE quer que cada uma alma um só possua;\nPor isso ornou de casto peito a Lua,\nQue o primeiro orbe ilustra cristalino;\n\nDe graça a Mãe formosa do Menino,\nQue nessa vista tem perdido a sua;\nPalas de ciência não maior que a tua:\nTem Juno da nobreza o império dino.\n\nMas junto agora o largo Céu derrama\nEm ti o mais que tinha, e foi o menos\nEm respeito do Autor da natureza.\n\nQue a seu pesar te dão, formosa dama,\nSeu peito a Lua, sua graça Venos,\nSua ciência Palas, Juno sua nobreza."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXLII, p. 72.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\n«Venos» (= Vênus, em rima com «menos») e «dões» mantidos.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Diversos_dões_reparte_o_Ceo_benino"}]}},
"luis-de-camoes-soneto-gentil-senhora-se-a-fortuna-imiga": {"t":["Gentil Senhora, se a Fortuna imiga,\nQue contra mi com todo o Céu conspira,\nOs olhos meus de ver os vossos tira,\nPorque em mais graves casos me persiga;\n\nComigo levo esta alma, que se obriga\nNa mor pressa de mar, de fogo, e d'ira,\nA dar-vos a memória, que suspira\nSó por fazer convosco eterna liga.\n\nNesta alma, onde a fortuna pode pouco,\nTão viva vos terei, que frio e fome,\nVos não possam tirar, nem mais perigos.\n\nAntes, com som de voz trêmulo e rouco\nPor vós chamando, só com vosso nome\nFarei fugir os ventos, e os imigos."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXLIII, p. 72.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nO índice do Wikisource dá o primeiro verso como 'Senhora minha, se a Fortuna imiga' (outra lição); a ed. de 1843 traz 'Gentil Senhora'.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Gentil_Senhora,_se_a_Fortuna_imiga"}]}},
"luis-de-camoes-soneto-que-modo-tao-sutil-da-natureza": {"t":["Que modo tão sutil da natureza\nPara fugir ao mundo e seus enganos!\nPermite que se esconda em tenros anos\nDebaixo de um burel tanta beleza!\n\nMas não pode esconder-se aquela alteza\nE gravidade de olhos soberanos,\nA cujo resplandor entre os humanos\nResistência não sinto, ou fortaleza.\n\nQuem quer livre ficar de dor e pena,\nVendo-a já, já trazendo-a na memória,\nNa mesma razão sua se condena.\n\nPorque quem mereceu ver tanta glória\nCativo há de ficar; que Amor ordena\nQue de juro tenha ela esta vitória."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXLIV, p. 73.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Que_modo_tão_subtil_da_natureza"}]}},
"luis-de-camoes-soneto-quando-se-vir-com-agua-o-fogo-arder": {"t":["Quando se vir com água o fogo arder,\nJuntar-se ao claro dia a noite escura,\nE a terra colocada lá na altura\nEm que se vem os céus prevalecer;\n\nQuando Amor à Razão obedecer,\nE em todos for igual uma ventura,\nDeixarei eu de ver tal formosura,\nE de a amar deixarei depois de a ver.\n\nPorém não sendo vista esta mudança\nNo mundo, porque, enfim, não pode ver-se,\nNinguém mudar-me queira de querer-vos.\n\nQue basta estar em vós minha esperança,\nE o ganhar-se a minha alma, ou o perder-se,\nPara dos olhos meus nunca perder-vos."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXLV, p. 73.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\n'vem' (v4) = veem, 3.ª p. pl. de ver, monossílabo na grafia da fonte; mantido.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quando_se_vir_com_água_o_fogo_arder"}]}},
"luis-de-camoes-soneto-quando-a-suprema-dor-muito-me-aperta": {"t":["Quando a suprema dor muito me aperta,\nSe digo que desejo esquecimento,\nÉ força que se faz ao pensamento,\nDe que a vontade livre desconcerta.\n\nAssi de erro tão grave me desperta\nA luz do bem regido entendimento,\nQue mostra ser engano, ou fingimento,\nDizer que em tal descanso mais se acerta.\n\nPorque essa própria imagem, que na mente\nMe representa o bem de que careço,\nFaz-mo de um certo modo ser presente.\n\nDitosa é, logo, a pena que padeço,\nPois que da causa dela em mi se sente\nUm bem que, inda sem ver-vos, reconheço."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXLVI, p. 74.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quando_a_suprema_dor_muito_me_aperta"}]}},
"luis-de-camoes-soneto-sempre-a-razao-vencida-foi-de-amor": {"t":["Sempre a Razão vencida foi de Amor;\nMas, porque assi o pedia o coração,\nQuis Amor ser vencido da Razão.\nOra que caso pode haver maior!\n\nNovo modo de morte, e nova dor!\nEstranheza de grande admiração!\nPois, enfim, seu vigor perde a afeição,\nPorque não perca a pena o seu vigor.\n\nFraqueza, nunca a houve no querer;\nMas antes muito mais se esforça assim\nUm contrário com outro por vencer.\n\nMas a razão que a luta vence, enfim,\nNão creio que é razão; mas deve ser\nInclinação que eu tenho contra mim."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXLIX, p. 75.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Sempre_a_Razão_vencida_foi_de_Amor"}]}},
"luis-de-camoes-soneto-julga-me-a-gente-toda-por-perdido": {"t":["Julga-me a gente toda por perdido,\nVendo-me, tão entregue a meu cuidado,\nAndar sempre dos homens apartado,\nE de humanos comércios esquecido.\n\nMas eu, que tenho o mundo conhecido,\nE quase que sobre ele ando dobrado,\nTenho por baixo, rústico, e enganado\nQuem não é com meu mal engrandecido.\n\nVá revolvendo a terra, o mar, e o vento,\nHonras busque e riquezas a outra gente,\nVencendo ferro, fogo, frio e calma.\n\nQue eu por amor somente me contento\nDe trazer esculpido eternamente\nVosso formoso gesto dentro da alma."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLI, p. 76.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Julga-me_a_gente_toda_por_perdido"}]}},
"luis-de-camoes-soneto-criou-a-natureza-damas-belas": {"t":["Criou a natureza Damas belas,\nQue foram de altos plectros celebradas;\nDelas tomou as partes mais prezadas,\nE a vós, Senhora, fez do melhor delas.\n\nElas diante vós são as estrelas,\nQue ficam com vos ver logo eclipsadas.\nMas se elas têm por sol essas rosadas\nLuzes de sol maior, felices elas!\n\nEm perfeição, em graça e gentileza,\nPor um modo entre humanos peregrino,\nA todo belo excede essa beleza.\n\nOh quem tivera partes de divino\nPara vos merecer! Mas se pureza\nDe amor vai ante vós, de vós sou dino."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLIII, p. 77.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\n«tẽe» (plural) atualizado para «têm»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Criou_a_natureza_Damas_bellas"}]}},
"luis-de-camoes-soneto-vencido-esta-de-amor-meu-pensamento": {"t":["Vencido está de amor meu pensamento\nO mais que pode ser, vencida a vida,\nSujeita a vos servir e instituída,\nOferecendo tudo a vosso intento.\n\nContente deste bem louva o momento,\nOu hora em que se viu tão bem perdida;\nMil vezes desejando, assi ferida,\nOutras mil renovar seu perdimento.\n\nCom esta pretensão está segura\nA causa que me guia nesta empresa\nTão sobrenatural, honrosa, e alta.\n\nJurando não querer outra ventura,\nVotando só por vós rara firmeza,\nOu ser no vosso amor achado em falta."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLIX, p. 80.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos, partidos em 6 + 4 na fonte; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nNa ed. de 1843 o soneto vem numa tabela de duas colunas (hemistíquios de 6 e 4 sílabas, que se leem também em separado); aqui cada linha da tabela forma um verso decassílabo, com a maiúscula da 2.ª coluna mantida só no texto bruto.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Vencido_está_de_amor_Meu_pensamento"}]}},
"luis-de-camoes-soneto-en-una-selva-al-dispuntar-del-dia": {"t":["En una selva al dispuntar del día\nEstaba Endimión triste y lloroso,\nVuelto al rayo del sol, que presuroso\nPor la falda de un monte descendía.\n\nMirando al turbador de su alegría,\nContrario de su bien y su reposo,\nTras un suspiro y otro, congojoso,\nRazones semejantes le decía:\n\nLuz clara, para mí la más escura,\nQue con ese paseo apresurado,\nMi sol con tu teniebla escureciste;\n\nSi allá pueden moverte en esa altura\nLas quejas de un pastor enamorado,\nNo tardes en volver a dó saliste."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLXV, p. 83.\n\n**Ortografia.** Castelhano; acentuação atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nSoneto em castelhano; a versão atualizada só acentua pela norma castelhana atual (formas antigas «dispuntar», «teniebla», «escura» mantidas)\n\nA página principal do Wikisource traz outra lição («despuntar», «Endemion», «congoxoso»...), de edição não identificada.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Página:Obras_completas_de_Luis_de_Camões_II_(1843).djvu/157"}]}},
"luis-de-camoes-soneto-orfeo-enamorado-que-tania": {"t":["Orfeo enamorado que tañía\nPor la perdida Ninfa que buscaba,\nEn el Orco implacable donde estaba,\nCon la arpa, y con la voz la enternecía.\n\nLa rueda de Ixión no se movía,\nNingún atormentado se quejaba;\nLas penas de los otros ablandaba,\nY todas las de todos él sentía.\n\nEl son pudo obligar de tal manera,\nQue en dulce galardón de lo cantado,\nLos infernales Reyes condolidos,\n\nLe mandaron volver su compañera,\nY volviola a perder el desdichado;\nCon que fueron entrambos los perdidos."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLXVI, p. 84.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto em castelhano (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página ligada no Anexo do Wikisource (https://pt.wikisource.org/wiki/Orfeu_enamorado_que_ta%C3%B1%C3%ADa) traz texto modernizado sem indicação de edição; aqui segue-se a ed. de 1843.\n\nSoneto em castelhano; o texto atualizado segue a ortografia castelhana atual (tañía, movía, Ixión, galardón, volviola a...)\n\nO Anexo do Wikisource dá o 1.º verso como «Orfeu enamorado que tañía»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/P%C3%A1gina:Obras_completas_de_Luis_de_Cam%C3%B5es_II_(1843).djvu/158"}]}},
"luis-de-camoes-soneto-eu-cantei-ja-e-agora-vou-chorando": {"t":["Eu cantei já, e agora vou chorando\nO tempo que cantei tão confiado:\nParece que no canto já passado\nSe estavam minhas lágrimas criando.\n\nCantei; mas se me alguém pergunta, quando?\nNão sei; que também fui nisso enganado.\nÉ tão triste este meu presente estado,\nQue o passado por ledo estou julgando.\n\nFizeram-me cantar manhosamente\nContentamentos não, mas confianças:\nCantava, mas já era ao som dos ferros.\n\nDe quem me queixarei, se tudo mente?\nPorém que culpas ponho às esperanças,\nOnde a fortuna injusta é mais qu'os erros?"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLXVII, p. 84.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Eu_cantei_ja,_e_agora_vou_chorando"}]}},
"luis-de-camoes-soneto-ai-amiga-cruel-que-apartamento": {"t":["Ai amiga cruel! que apartamento\nÉ este que fazeis da pátria terra?\nAi! quem do amado ninho vos desterra,\nGlória dos olhos, bem do pensamento?\n\nIs tentar da fortuna o movimento,\nE dos ventos cruéis a dura guerra?\nVer brenhas de ondas? feito o mar em serra\nLevantado de um vento e de outro vento?\n\nMas já que vós partis, sem vos partirdes,\nParta convosco o Céu tanta ventura,\nQue se avantaje àquela qu'esperardes.\n\nE só desta verdade ide segura,\nQue fazeis mais saudades com vos irdes,\nDo que levais desejos por chegardes."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLXVIII, p. 85.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\nO Wikisource lista este soneto como «Ah! imiga cruel, que apartamento»; a ed. de 1843 traz «Ai amiga cruel!»; «Is» (fonte: «His») = ides.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Ai_amiga_cruel!_que_apartamento"}]}},
"luis-de-camoes-soneto-ah-minha-dinamene-assi-deixaste": {"t":["Ah minha Dinamene! assi deixaste\nQuem nunca deixar pôde de querer-te!\nQue já, Ninfa gentil, não possa ver-te!\nQue tão veloz a vida desprezaste!\n\nComo por tempo eterno te apartaste\nDe quem tão longe andava de perder-te?\nPuderam essas águas defender-te\nQue não visses quem tanto magoaste?\n\nNem somente falar-te a dura morte\nMe deixou, qu'apressada o negro manto\nLançar sobre os teus olhos consentiste.\n\nOh mar! oh céu! oh minha escura sorte!\nQual vida perderei que valha tanto,\nSe inda tenho por pouco o viver triste?"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLXX, p. 86.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Ah_minha_Dinamene!_assi_deixaste"}]}},
"luis-de-camoes-soneto-guardando-em-mi-a-sorte-o-seu-direito": {"t":["Guardando em mi a Sorte o seu direito.\nEm verde me cortou minha alegria.\nOh quanto feneceu naquele dia,\nCuja triste lembrança arde em meu peito!\n\nQuando mais o imagino, bem suspeito\nQue a tal bem tal desconto se devia,\nPor não dizer o mundo que podia\nAchar-se em seus enganos bem perfeito.\n\nPois se a Fortuna o fez por descontar-me\nAquele gosto, em cujo sentimento\nA memória não faz senão matar-me;\n\nQue culpas pode dar-me o pensamento,\nSe a causa qu'ele tem de atormentar-me,\nTenho eu de sofrer mal o seu tormento?"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLXXI, p. 86.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nO Anexo do Wikisource lista este soneto pela lição moderna «Fortuna em mi guardando seu direito»; a ed. de 1843 traz «Guardando em mi a Sorte o seu direito»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Guardando_em_mi_a_Sorte_o_seu_direito"}]}},
"luis-de-camoes-soneto-cantando-estava-um-dia-bem-seguro": {"t":["Cantando estava um dia bem seguro,\nQuando passava Sílvio, e me dizia:\n(Sílvio, pastor antiguo que sabia\nPor o canto das aves o futuro)\n\nLiso, quando quiser o fado escuro,\nA oprimir-te virão em um só dia\nDous lobos; logo a voz e a melodia\nTe fugirão, e o som suave e puro.\n\nBem foi assi; porque um me degolou\nQuanto gado vacum pastava e tinha,\nDe que grandes soldadas esperava.\n\nE por mais dano o outro me matou\nA cordeira gentil, qu'eu tanto amava,\nPerpétua saudade da alma minha."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLXXII, p. 87.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CED)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Cantando_estava_hum_dia_bem_seguro"}]}},
"luis-de-camoes-soneto-o-ceu-a-terra-o-vento-sossegado": {"t":["O céu, a terra, o vento sossegado,\nAs ondas que se estendem por a areia,\nOs peixes que no mar o sono enfreia,\nO noturno silêncio repousado;\n\nO Pescador Aônio que, deitado\nOnde co'o vento a água se meneia,\nChorando, o nome amado em vão nomeia,\nQue não pode ser mais que nomeado,\n\nOndas, (dizia) antes que Amor me mate,\nTornai-me a minha Ninfa, que tão cedo\nMe fizestes à morte estar sujeita.\n\nNinguém responde; o mar de longe bate;\nMove-se brandamente o arvoredo;\nLeva-lhe o vento a voz, qu'ao vento deita."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLXXIII, p. 87.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/O_ceo,_a_terra,_o_vento_socegado"}]}},
"luis-de-camoes-soneto-ah-fortuna-cruel-ah-duros-fados": {"t":["Ah Fortuna cruel! ah duros Fados!\nQuão asinha em meu dano vos mudastes!\nCom os vossos cuidados me cansastes,\nE agora descansais co'os meus cuidados.\n\nFizestes-me provar gostos passados,\nE vossa condição neles provastes:\nSingelos em um'hora mos levastes,\nDeixando em seu lugar males dobrados.\n\nQuanto melhor me fora que não vira\nOs doces bens de Amor? Ah bens suaves!\nQuem me deixa sem vós, por que me deixa?\n\nDe queixar-te, alma minha, te retira:\nAlma, de alto caída em penas graves,\nPois tanto amaste em vão, em vão te queixa."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLXXIV, p. 88.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\n«porque» interrogativo atualizado para «por que»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Ah_Fortuna_cruel!_ah_duros_Fados!"}]}},
"luis-de-camoes-soneto-lembrancas-que-lembrais-o-bem-passado": {"t":["Lembranças, que lembrais o bem passado\nPara que sinta mais o mal presente,\nDeixai-me, se quereis, viver contente,\nMorrer não me deixeis em tal estado.\n\nSe de todo, contudo, está do Fado,\nQue eu morra de viver tão descontente,\nVenha-me todo o bem por acidente,\nE todo o mal me venha por cuidado.\n\nQue muito melhor é perder-se a vida,\nPerdendo-se as lembranças da memória,\nPois fazem tanto dano ao pensamento.\n\nPorque, enfim, nada perde quem perdida\nA esperança tem já daquela glória\nQue fazia suave o seu tormento."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLXXVI, p. 89.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nO Anexo do Wikisource dá o 1.º verso como «Lembranças, que lembrais meu bem passado»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Lembran%C3%A7as,_que_lembrais_o_bem_passado"}]}},
"luis-de-camoes-soneto-por-sua-ninfa-cefalo-deixava": {"t":["Por sua Ninfa Céfalo deixava\nA Aurora, que por ele se perdia,\nPosto que dá princípio ao claro dia,\nPosto que as roxas flores imitava.\n\nEle, que a bela Prócris tanto amava,\nQue só por ela tudo enjeitaria,\nDeseja de tentar se lhe acharia\nTão firme fé, como ela nele achava.\n\nMudado o traje, tece um duro engano;\nOutro se finge, preço põe diante;\nQuebra-se a fé mudável, e consente.\n\nOh sutil invenção para seu dano!\nVede que manhas busca um cego amante\nPara que sempre seja descontente!"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLXXXIII, p. 92.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Por_sua_Nympha_C%C3%A9phalo_deixava"}]}},
"luis-de-camoes-soneto-sentindo-se-alcancada-a-bela-esposa": {"t":["Sentindo-se alcançada a bela esposa\nDe Céfalo no crime consentido,\nPara os montes fugia do marido;\nE não sei se de astuta, ou vergonhosa.\n\nPorque ele, enfim, sofrendo a dor ciosa,\nDa cegueira obrigado de Cupido,\nApós ela se vai como perdido,\nJá perdoando a culpa criminosa.\n\nDeita-se aos pés da Ninfa endurecida,\nQue do cioso engano está agravada;\nJá lhe pede perdão, já pede a vida.\n\nOh força d'afeição desatinada!\nQue da culpa contr'ele cometida,\nPerdão pedia à parte que é culpada!"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLXXXIV, p. 93.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nO índice do Wikisource dá o primeiro verso como 'Sentindo-se tomada a bela esposa' (outra lição); a ed. de 1843 traz 'alcançada'.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Sentindo-se_alcançada_a_bella_esposa"}]}},
"luis-de-camoes-soneto-seguia-aquele-fogo-que-o-guiava": {"t":["Seguia aquele fogo, que o guiava,\nLeandro, contra o mar e contra o vento;\nQuebravam-lhe ondas o animoso alento,\nPor mais e mais que Amor lho renovava.\n\nCom sentir já que quase lhe faltava,\nSem nada esmorecer, no pensamento\n(Não podendo falar) de seu intento\nO fim ao surdo mar encomendava.\n\nÓ mar, (dizia o moço só consigo)\nJá te não peço a vida; só queria\nQue a d'Hero me salvasses: não me veja:\n\nEste defunto corpo lá o desvia\nD'aquela torre: sê-me nisto amigo,\nPois no meu maior bem me houveste inveja."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLXXXV, p. 93.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Seguia_aquelle_fogo,_que_o_guiava"}]}},
"luis-de-camoes-soneto-ornou-sublime-esforco-ao-grande-atlante": {"t":["Ornou sublime esforço ao grande Atlante,\nCom qu'a celeste máquina sustenta;\nHonrou a Homero o engenho, com que intenta\nGrécia do quarto céu passá-lo avante;\n\nCoroou claro Amor de amor constante\nA Orfeu, na paz firme e na tormenta;\nInspirou a Fortuna, em tudo isenta,\nA César, de quem foi um tempo amante;\n\nExaltaste tu, Fama, a glória alta\nDe Alcides lá no monte em que resides;\nMas Castro, em quem o Céu seus dões derrama,\n\nMais orna, honra, coroa, inspira, exalta,\nQue Atlante, Homero, Orfeu, César e Alcides,\nEsforço, engenho, Amor, Fortuna e Fama."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CLXXXIX, p. 95.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nO Anexo do Wikisource lista este soneto pela lição moderna «Ornou mui raro esforço ao grande Atlante»; a ed. de 1843 traz «Ornou sublime esforço»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Ornou_sublime_esf%C3%B4r%C3%A7o_ao_grande_Atlante"}]}},
"luis-de-camoes-soneto-despois-que-viu-cibele-o-corpo-humano": {"t":["Despois que viu Cibele o corpo humano\nDo formoso Átis seu verde pinheiro,\nEm piedade o vão furor primeiro\nConvertido, chorava o grave dano.\n\nE, à sua dor fazendo ilustre engano,\nA Júpiter pediu, que o verdadeiro\nPreço da nobre palma e do loureiro\nAo seu pinheiro desse, soberano.\n\nMais lhe concede o filho poderoso\nQue, crescendo, as estrelas tocar possa,\nVendo os segredos lá do céu superno.\n\nOh ditoso pinheiro! oh mais ditoso\nQuem se vir coroar da rama vossa,\nCantando à vossa sombra verso eterno!"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXC, p. 96.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\n«Atys» atualizado para «Átis»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Despois_que_vio_Cibele_o_corpo_humano"}]}},
"luis-de-camoes-soneto-erros-meus-ma-fortuna-amor-ardente": {"t":["Erros meus, má Fortuna, Amor ardente\nEm minha perdição se conjuraram:\nOs erros e a Fortuna sobejaram;\nQue para mi bastava Amor somente.\n\nTudo passei; mas tenho tão presente\nA grande dor das cousas, que passaram,\nQue já as frequências suas me ensinaram\nA desejos deixar de ser contente.\n\nErrei todo o discurso de meus anos;\nDei causa a que a Fortuna castigasse\nAs minhas mal fundadas esperanças.\n\nDe Amor não vi senão breves enganos.\nOh quem tanto pudesse, que fartasse\nEste meu duro Gênio de vinganças!"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXCIII, p. 97.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Erros_meus,_ma_Fortuna,_Amor_ardente"}]}},
"luis-de-camoes-soneto-ca-nesta-babilonia-donde-mana": {"t":["Cá nesta Babilônia donde mana\nMatéria a quanto mal o mundo cria;\nCá donde o puro Amor não tem valia;\nQue a Mãe, que manda mais, tudo profana;\n\nCá donde o mal se afina, o bem se dana,\nE pode mais que a honra a tirania;\nCá donde a errada e cega Monarquia\nCuida que um nome vão a Deus engana;\n\nCá neste labirinto onde a Nobreza,\nO Valor e o Saber pedindo vão\nÀs portas da Cobiça e da Vileza;\n\nCá neste escuro caos de confusão\nCumprindo o curso estou da natureza.\nVê se me esquecerei de ti, Sião!"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXCIV, p. 98.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nO Wikisource lista este soneto como «Cá nesta Babilónia, donde mana»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Cá_nesta_Babylonia_donde_mana"}]}},
"luis-de-camoes-soneto-correm-turbas-as-aguas-deste-rio": {"t":["Correm turbas as águas deste rio,\nQue as rápidas enchentes enturbaram;\nOs florescidos campos se secaram;\nIntratável se fez o vale e frio.\n\nPassou, como o verão, o ardente estio;\nUmas cousas por outras se trocaram:\nOs fementidos fados já deixaram\nDo mundo o regimento, ou desvario.\n\nJá o tempo a ordem sua tem sabida;\nO mundo não; mas anda tão confuso,\nQue parece que dele Deus se esquece.\n\nCasos, opiniões, natura, e uso,\nFazem que nos pareça desta vida\nQue não há nela mais do que parece."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXCV, p. 98.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\nA ed. de 1843 traz «turbas» (outras edições: «turvas»); «florecidos» atualizado para «florescidos»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Correm_turbas_as_águas_deste_rio"}]}},
"luis-de-camoes-soneto-vos-outros-que-buscais-repouso-certo": {"t":["Vós outros, que buscais repouso certo\nNa vida, com diversos exercícios;\nA quem, vendo do mundo os benefícios,\nO regimento seu fica encoberto;\n\nDedicai, se quereis, ao Desconcerto\nNovas honras e cegos sacrifícios;\nQue, por castigo igual de antiguos vícios,\nQuer Deus que andem as cousas por acerto.\n\nNão caiu neste modo de castigo\nQuem pôs culpa à Fortuna, quem somente\nCrê que acontecimentos há no mundo.\n\nA grande experiência é grão perigo:\nMas o que a Deus é justo e evidente\nParece injusto aos homens e profundo."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXCVI, p. 99.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\n'antiguos' (v7) mantido como na fonte (forma antiga, trissílaba)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Vós_outros,_que_buscais_repouso_certo"}]}},
"luis-de-camoes-soneto-para-se-namorar-do-que-criou": {"t":["Para se namorar do que criou,\nTe fez Deus, sacra Fênix, Virgem pura.\nVede que tal seria esta feitura\nQue para si o seu Feitor guardou!\n\nNo seu alto conceito te formou\nPrimeiro que a primeira criatura,\nPara que única fosse a compostura\nQue de tão longo tempo se estudou.\n\nNão sei se digo em tudo quanto baste\nPara exprimir as raras qualidades\nQue quis criar em ti quem tu criaste.\n\nÉs Filha, Mãe, e Esposa: e se alcançaste\nUma só, três tão altas dignidades,\nFoi porqu'a Três de Um só tanto agradaste."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXCVII, p. 99.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC CDC)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Para_se_namorar_do_que_criou"}]}},
"luis-de-camoes-soneto-desce-do-ceu-imenso-deus-benino": {"t":["Desce do céu imenso Deus benino\nPara encarnar na Virgem soberana.\nPor que desce o divino a cousa humana?\nPara subir o humano a ser divino.\n\nPois como vem tão pobre e tão menino,\nRendendo-se ao poder da mão tirana?\nPorque vem receber morte inumana\nPara pagar de Adão o desatino.\n\nÉ possível que os dous o fruto comem\nQue de quem lhes deu tanto foi vedado?\nSi; porque o próprio ser de deuses tomem.\n\nE por esta razão foi humanado?\nSi; porque foi com causa decretado,\nSe quis o homem ser Deus, que Deus fosse homem."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXCVIII, p. 100.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DDC)\n\n**Notas sobre o texto.**\n\nOutras edições: «Dece do Céu imenso»; «Porque» interrogativo atualizado para «Por que»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Desce_do_ceo_immenso_Deos_benino"}]}},
"luis-de-camoes-soneto-dos-ceus-a-terra-desce-a-mor-beleza": {"t":["Dos céus à terra desce a mor Beleza,\nUne-se à nossa carne, e a faz nobre;\nE, sendo a humanidade d'antes pobre,\nHoje subida fica à mor riqueza.\n\nBusca o Senhor mais rico a mor pobreza;\nQue, como ao mundo o seu amor descobre,\nDe palhas vis o corpo tenro cobre,\nE por elas o mesmo céu despreza.\n\nComo? Deus em pobreza à terra desce?\nO qu'é mais pobre tanto lhe contenta,\nQu'este somente rico lhe parece.\n\nPobreza este Presépio representa;\nMas tanto por ser pobre já merece,\nQue quanto mais o é, mais lhe contenta."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CXCIX, p. 100.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\n«dece» (v. 9) atualizado para «desce»; outras edições: «Dos Céus à terra dece a mor beleza»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Dos_ceos_á_terra_desce_a_mor_Belleza"}]}},
"luis-de-camoes-soneto-porque-a-tamanhas-penas-se-oferece": {"t":["Porque a tamanhas penas se oferece\nPor o pecado alheio, e erro insano,\nO Trino Deus? Porque o sojeito humano\nNão pode co'o castigo que merece.\n\nQuem padecerá as penas que padece?\nQuem sofrerá desonra, morte e dano?\nQuem será, se não for o Soberano\nQue reina, e servos manda, e obedece?\n\nFoi a força do homem tão pequena,\nQue não pôde soster tanta aspereza,\nPois não sosteve a Lei que Deus ordena.\n\nMas sofre-a aquela imensa Fortaleza\nPor amor puro; que a mortal fraqueza\nFoi para o erro, e não já para a pena."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CC, p. 101.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DDC)\n\n**Notas sobre o texto.**\n\n«sogeito» (fonte) > «sojeito»: mantida a vogal da forma antiga (hoje «sujeito»)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Porque_a_tamanhas_penas_se_offerece"}]}},
"luis-de-camoes-soneto-onde-mereci-eu-tal-pensamento": {"t":["Onde mereci eu tal pensamento\nNunca de ser humano merecido?\nOnde mereci eu ficar vencido\nDe quem tanto me honrou co'o vencimento?\n\nEm glória se converte o meu tormento,\nQuando vendo-me estou tão bem perdido;\nPois não foi tanto mal ser atrevido,\nComo foi glória o mesmo atrevimento.\n\nVivo, Senhora, só de contemplar-vos;\nE pois esta alma tenho tão rendida,\nEm lágrimas desfeito acabarei.\n\nPorque não me farão deixar de amar-vos\nReceios de perder por vós a vida;\nQue por vós vezes mil a perderei."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCII, p. 102.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Onde_mereci_eu_tal_pensamento"}]}},
"luis-de-camoes-soneto-de-frescas-belvederes-rodeadas": {"t":["De frescas belvederes rodeadas\nEstão as puras águas desta fonte;\nFormosas Ninfas lhes estão defronte,\nA vencer e a matar acostumadas.\n\nAndam contra Cupido levantadas\nAs suas graças, que não há quem conte:\nD'outro vale esquecidas, d'outro monte,\nA vida passam neste sossegadas.\n\nO seu poder juntou, sua valia\nAmor, já não sofrendo este desprezo,\nSomente por se ver delas vingado;\n\nMas, vendo-as, entendeu que não podia\nDe ser morto livrar-se, ou de ser preso,\nE ficou-se com elas desarmado."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCIII, p. 102.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/De_frescas_belvederes_rodeadas"}]}},
"luis-de-camoes-soneto-nos-bracos-de-um-silvano-adormecendo": {"t":["Nos braços de um Silvano adormecendo\nSe estava aquela Ninfa qu'eu adoro,\nPagando com a boca o doce foro,\nCom que os meus olhos foi escurecendo.\n\nOh bela Vênus! porqu'estás sofrendo\nQue a maior formosura do teu coro\nEm um poder tão vil perca o decoro\nQue o mérito maior lhe está devendo?\n\nEu levarei daqui por pressuposto\nDesta nova estranheza que fizeste,\nQue em ti não pode haver cousa segura.\n\nQue, pois o claro lume, o belo rosto\nÀquele monstro tão disforme deste,\nNão creio qu'haja Amor, senão Ventura."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCIV, p. 103.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Nos_bra%C3%A7os_de_hum_Sylvano_adormecendo"}]}},
"luis-de-camoes-soneto-quem-diz-que-amor-e-falso-ou-enganoso": {"t":["Quem diz que Amor é falso, ou enganoso,\nLigeiro, ingrato, vão, desconhecido,\nSem falta lhe terá bem merecido\nQue lhe seja cruel, ou rigoroso,\n\nAmor é brando, é doce, e é piedoso:\nQuem o contrário diz não seja crido;\nSeja por cego e apaixonado tido,\nE aos homens, e inda aos deuses odioso.\n\nSe males faz Amor, em mi se vem;\nEm mi mostrando todo o seu rigor,\nAo mundo quis mostrar quanto podia.\n\nMas todas suas iras são d'Amor;\nTodos estes seus males são um bem,\nQu'eu por todo outro bem não trocaria."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCV, p. 103.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\n'se vem' (v9) = se veem (3.ª p. pl. de ver), monossílabo, em rima com 'bem'; mantido.\n\nSoneto ausente dos 166 sonetos do texto-base de Costa Pimpão (Biblioteca Virtual do Estudante Brasileiro, USP); atribuição possivelmente duvidosa.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quem_diz_que_Amor_he_falso,_ou_enganoso"}]}},
"luis-de-camoes-soneto-nem-o-tremendo-estrepito-da-guerra": {"t":["Nem o tremendo estrépito da guerra\nCom armas, com incêndios espantosos\nQue despacham pelouros perigosos,\nBastantes a abalar uma alta serra,\n\nPodem pôr medo a quem nenhum encerra,\nDespois que viu os olhos tão formosos,\nPor quem o horror nos casos pavorosos\nDe mi todo se aparta e se desterra,\n\nA vida posso ao fogo e ferro dar,\nE perdê-la em qualquer duro perigo,\nE nele, como fênix, renovar.\n\nNão pode mal haver para comigo,\nDe qu'eu já me não possa bem livrar,\nSenão do que me ordena Amor imigo."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCX, p. 106.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nA página ligada no Anexo do Wikisource (https://pt.wikisource.org/wiki/Nem_o_tremendo_estr%C3%A9pito_da_guerra) traz texto modernizado sem indicação de edição; aqui segue-se a ed. de 1843.\n\nVariantes na página do Anexo: v. 4 «ũa alta serra»; v. 6 «depois ... fermosos»; v. 12 «pera comigo»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/P%C3%A1gina:Obras_completas_de_Luis_de_Cam%C3%B5es_II_(1843).djvu/180"}]}},
"luis-de-camoes-soneto-fiou-se-o-coracao-de-muito-isento": {"t":["Fiou-se o coração, de muito isento,\nDe si, cuidando mal que tomaria\nTão ilícito amor, tal ousadia,\nTal modo nunca visto de tormento.\n\nMas os olhos pintaram tão a tento\nOutros que vistos têm na fantasia,\nQue a razão, temerosa do que via,\nFugiu, deixando o campo ao pensamento.\n\nÓ Hipólito casto, que de jeito\nDe Fedra tua madrasta foste amado,\nQue não sabia ter nenhum respeito;\n\nEm mi vingou Amor teu casto peito:\nMas está deste agravo tão vingado,\nQue se arrepende já do que tem feito."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCXI, p. 106.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC CDC)\n\n**Notas sobre o texto.**\n\nA página ligada no Anexo do Wikisource (https://pt.wikisource.org/wiki/Fiou-se_o_cora%C3%A7%C3%A3o,_de_muito_isento) traz texto modernizado sem indicação de edição; aqui segue-se a ed. de 1843.\n\n«tẽe» da fonte = têm (sujeito: os olhos)\n\nVariantes na página do Anexo: v. 12 «Em mim vingou o Amor teu casto peito»; v. 13 «desse agravo»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/P%C3%A1gina:Obras_completas_de_Luis_de_Cam%C3%B5es_II_(1843).djvu/180"}]}},
"luis-de-camoes-soneto-que-me-quereis-perpetuas-saudades": {"t":["Que me quereis perpétuas saudades?\nCom qu'esperanças inda me enganais?\nO tempo, que se vai, não torna mais,\nE se torna, não tornam as idades.\n\nRazão é já, ó anos, que vos vades,\nPorque estes tão ligeiros que passais,\nNem todos para um gosto sois iguais,\nNem sempre são conformes as vontades.\n\nAquilo a que já quis é tão mudado,\nQue quase é outra cousa; porque os dias\nTêm o primeiro gosto já danado.\n\nEsperanças de novas alegrias,\nNão m'as deixa a Fortuna e o tempo irado,\nQue do contentamento são espias."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCXX, p. 111.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Que_me_quereis_perpétuas_saudades%3F"}]}},
"luis-de-camoes-soneto-vos-ninfas-da-gangetica-espessura": {"t":["Vós, Ninfas da Gangética espessura,\nCantai suavemente, em voz sonora,\nUm grande Capitão que a roxa Aurora\nDos filhos defendeu da noite escura.\n\nAjuntou-se a caterva negra e dura,\nQue na Áurea Quersoneso afouta mora,\nPara lançar do caro ninho fora\nAqueles que mais podem que a ventura.\n\nMas um forte leão, com pouca gente,\nA multidão tão fera como néscia,\nDestruindo castiga e torna fraca.\n\nÓ Ninfas, cantai, pois; que claramente\nMais do que Leônidas fez em Grécia,\nO nobre Leoniz fez em Malaca."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCXXVIII, p. 115.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nO Wikisource lista este soneto como «A D. Leonis Pereira»; um dos poucos poemas publicados em vida de Camões, na História da Província de Santa Cruz de Pero de Magalhães Gândavo (1576)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Vós_Nymphas_da_Gangetica_espessura"}]}},
"luis-de-camoes-soneto-alma-gentil-que-a-firme-eternidade": {"t":["Alma gentil, que à firme eternidade\nSubiste clara e valerosamente,\nCá durará de ti perpetuamente\nA fama, a glória, o nome e a saudade.\n\nNão sei se é mor espanto em tal idade\nDeixar de teu valor inveja à gente,\nSe um peito de diamante, ou de serpente,\nFazeres que se mova a piedade.\n\nInvejosa da tua acho mil sortes,\nE a minha mais que todas invejosa,\nPois ao teu mal o meu tanto igualaste.\n\nOh ditoso morrer! sorte ditosa!\nPois o que não se alcança com mil mortes,\nTu com uma só morte o alcançaste."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCXXIX, p. 115.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Alma_gentil,_que_á_firme_eternidade"}]}},
"luis-de-camoes-soneto-debaixo-desta-pedra-sepultada": {"t":["Debaixo desta pedra sepultada\nJaz do mundo a mais nobre formosura,\nA quem a morte, só de inveja pura,\nSem tempo sua vida tem roubada,\n\nSem ter respeito àquela assi estremada\nGentileza de luz, que a noite escura\nTornava em claro dia; cuja alvura\nDo sol a clara luz tinha eclipsada.\n\nDo sol peitada foste, cruel morte,\nPara o livrar de quem o escurecia;\nE da lua, que ante ela luz não tinha.\n\nComo de tal poder tiveste sorte?\nE se a tiveste, como tão asinha\nTornaste a luz do mundo em terra fria?"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCXXX, p. 116.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CED)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Debaixo_desta_pedra_sepultada"}]}},
"luis-de-camoes-soneto-quanta-incerta-esperanca-quanto-engano": {"t":["Quanta incerta esperança, quanto engano!\nQuanto viver de falsos pensamentos!\nPois todos vão fazer seus fundamentos\nSó no mesmo em qu'está seu próprio dano.\n\nNa incerta vida estribam de um humano;\nDão crédito a palavras que são ventos;\nChoram despois as horas e os momentos,\nQue riram com mais gosto em todo o ano.\n\nNão haja em aparências confianças;\nEntendei que o viver é de emprestado;\nQue o de que vive o mundo são mudanças.\n\nMudai, pois, o sentido e o cuidado,\nSomente amando aquelas esperanças\nQue duram para sempre com o amado."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCXXXII, p. 117.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nSoneto ausente dos 166 sonetos do texto-base de Costa Pimpão (Biblioteca Virtual do Estudante Brasileiro, USP); atribuição possivelmente duvidosa.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quanta_incerta_esperança,_quanto_engano!"}]}},
"luis-de-camoes-soneto-como-podes-oh-cego-pecador": {"t":["Como podes (oh cego pecador!)\nEstar em teus errores tão isento,\nSabendo que esta vida é um momento,\nSe comparada com a eterna for?\n\nNão cuides tu que o justo Julgador\nDeixará tuas culpas sem tormento,\nNem que passando vai o tempo lento\nDo dia de horrendíssimo pavor.\n\nNão gastes horas, dias, meses, anos,\nEm seguir de teus danos a amizade\nDe que despois resultam mores danos.\n\nE pois de teus enganos a verdade\nConheces, deixa já tantos enganos,\nPedindo a Deus perdão com humildade."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCXXXV, p. 118.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Como_podes_(oh_cego_peccador!)"}]}},
"luis-de-camoes-soneto-verdade-amor-razao-merecimento": {"t":["Verdade, Amor, Razão, Merecimento,\nQualquer alma farão segura e forte;\nPorém Fortuna, Caso, Tempo, e Sorte,\nTêm do confuso mundo o regimento.\n\nEfeitos mil revolve o pensamento,\nE não sabe a que causa se reporte:\nMas sabe que o que é mais que vida e morte\nNão se alcança de humano entendimento.\n\nDoutos varões darão razões subidas;\nMas são as exp'riências mais provadas:\nE portanto é melhor ter muito visto.\n\nCousas há i que passam sem ser cridas:\nE cousas cridas há sem ser passadas.\nMas o melhor de tudo é crer em Cristo."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCXXXVI, p. 119.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\n'hi' (v12) atualizado para 'i' (advérbio antigo = aí)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Verdade,_Amor,_Razão,_Merecimento"}]}},
"luis-de-camoes-soneto-ditosas-almas-que-ambas-juntamente": {"t":["Ditosas almas, que ambas juntamente\nAo céu de Vênus e de Amor voastes,\nOnde um bem que tão breve cá lograstes,\nEstais logrando agora eternamente;\n\nAquele estado vosso tão contente,\nQue só por durar pouco triste achastes,\nPor outro mais contente já o trocastes,\nOnde sem sobressalto o bem se sente.\n\nTriste de quem cá vive tão cercado,\nNa amorosa fineza, de um tormento\nQue a glória lhe perturba mais crescida!\n\nTriste, pois me não val o sofrimento,\nE Amor para mais dano me tem dado\nPara tão duro mal tão larga vida!"],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCXLVII, p. 124.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\nPágina do Wikisource não revista (texto importado do Projeto Gutenberg n.º 31509, que reproduz esta edição); conferido com a página principal do Wikisource, que traz texto modernizado de outra edição, com variantes.\n\nÚltimo verso partido entre duas páginas («larg-» / «a vida!»), unido.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Página:Obras_completas_de_Luis_de_Camões_II_(1843).djvu/198"}]}},
"luis-de-camoes-soneto-contente-vivi-ja-vendo-me-isento": {"t":["Contente vivi já, vendo-me isento\nDeste mal de que a muitos queixar via:\nChamam-lhe amor; mas eu lhe chamaria\nDiscórdia e sem-razão, guerra e tormento.\n\nEnganou-me co'o nome o pensamento:\n(Quem com tal nome não se enganaria?)\nAgora tal estou, que temo um dia\nEm que venha a faltar-me o sofrimento.\n\nCom desesperação, e com desejo\nMe paga o que por ele estou passando,\nE inda está do meu mal mal satisfeito.\n\nPois sobre tantos danos inda vejo\nPara dar-me outros mil um olhar brando,\nE para os não curar um duro peito."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCXLVIII, p. 125.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nPágina do Wikisource não revista (texto importado do Projeto Gutenberg n.º 31509, que reproduz esta edição); conferido com a página principal do Wikisource, que traz texto modernizado de outra edição, com variantes.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Página:Obras_completas_de_Luis_de_Camões_II_(1843).djvu/199"}]}},
"luis-de-camoes-soneto-doce-contentamento-ja-passado": {"t":["Doce contentamento já passado,\nEm que todo o meu bem só consistia,\nQuem vos levou de minha companhia,\nE me deixou de vós tão apartado?\n\nQuem cuidou que se visse neste estado\nNaquelas breves horas d'alegria,\nQuando minha ventura consentia\nQue d'enganos vivesse meu cuidado?\n\nFortuna minha foi cruel e dura\nAquela que causou meu perdimento,\nCom a qual ninguém pode ter cautela.\n\nNem se engane nenhuma criatura;\nQue não pode nenhum impedimento\nFugir o que lh'ordena sua estrela."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCLXV, p. 133.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nPágina do Wikisource não revista (texto importado do Projeto Gutenberg n.º 31509, que reproduz esta edição); conferido com a página principal do Wikisource, que traz texto modernizado de outra edição, com variantes.\n\nO ponto final do último verso está na página seguinte.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Página:Obras_completas_de_Luis_de_Camões_II_(1843).djvu/207"}]}},
"luis-de-camoes-soneto-este-amor-que-vos-tenho-limpo-e-puro": {"t":["Este amor, que vos tenho limpo e puro,\nDe pensamento vil nunca tocado,\nEm minha tenra idade começado,\nTê-lo dentro nesta alma só procuro.\n\nD'haver nele mudança estou seguro,\nSem temer nenhum caso, ou duro fado,\nNem o supremo bem, ou baixo estado,\nNem o tempo presente, nem futuro.\n\nA bonina e a flor asinha passa;\nTudo por terra o inverno e estio deita;\nSó para meu amor é sempre Maio.\n\nMas ver-vos para mim, Senhora, escassa,\nE qu'essa ingratidão tudo me enjeita,\nTraz este meu amor sempre em desmaio."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCLXVIII, p. 135.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Este_amor,_que_vos_tenho_limpo_e_puro"}]}},
"luis-de-camoes-soneto-a-formosura-desta-fresca-serra": {"t":["A formosura desta fresca serra,\nE a sombra dos verdes castanheiros,\nO manso caminhar destes ribeiros,\nDonde toda a tristeza se desterra;\n\nO rouco som do mar, a estranha terra,\nO esconder do sol pelos outeiros,\nO recolher dos gados derradeiros,\nDas nuvens pelo ar a branda guerra:\n\nEnfim, tudo o que a rara natureza\nCom tanta variedade nos ofrece,\nM'está (se não te vejo) magoando.\n\nSem ti tudo me enoja, e me aborrece;\nSem ti perpetuamente estou passando\nNas mores alegrias mor tristeza."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCLXIX, p. 135.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DEC)\n\n**Notas sobre o texto.**\n\nOutras edições: «A fermosura desta fresca serra» (a ed. de 1843 normaliza fermoso > formoso)\n\n«ofrece» (fonte: «offrece») é forma sincopada de «oferece» (3 sílabas); mantida.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/A_formosura_desta_fresca_serra"}]}},
"luis-de-camoes-soneto-ja-nao-sinto-senhora-os-desenganos": {"t":["Já não sinto, Senhora, os desenganos,\nCom que minha afeição sempre tratastes,\nNem ver o galardão, que me negastes,\nMerecido por fé há tantos anos.\n\nA mágoa choro só, só choro os danos\nDe ver por quem, Senhora, me trocastes;\nMas em tal caso vós só me vingastes\nDe vossa ingratidão, vossos enganos.\n\nDobrada glória dá qualquer vingança,\nQue o ofendido toma do culpado,\nQuando se satisfaz com causa justa;\n\nMas eu de vossos males e esquivança,\nDe que agora me vejo bem vingado,\nNão a quisera tanto à vossa custa."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCLXXI, p. 136.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página ligada no Anexo do Wikisource (https://pt.wikisource.org/wiki/J%C3%A1_n%C3%A3o_sinto,_Senhora,_os_desenganos) traz texto modernizado sem indicação de edição; aqui segue-se a ed. de 1843.\n\nPágina do Wikisource ainda não revisada (nível 1, importada do Projeto Gutenberg n.º 31509); texto conferido verso a verso com o Gutenberg; a última palavra do soneto está na página seguinte do Wikisource (https://pt.wikisource.org/wiki/P%C3%A1gina:Obras_completas_de_Luis_de_Cam%C3%B5es_II_(1843).djvu/211), por divisão automática do texto.\n\nVariantes na página do Anexo: v. 11 «cousa justa»; v. 14 «não o quisera eu tanto»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/P%C3%A1gina:Obras_completas_de_Luis_de_Cam%C3%B5es_II_(1843).djvu/210 e https://pt.wikisource.org/wiki/P%C3%A1gina:Obras_completas_de_Luis_de_Cam%C3%B5es_II_(1843).djvu/211"}]}},
"luis-de-camoes-soneto-eu-vivia-de-lagrimas-isento": {"t":["Eu vivia de lágrimas isento,\nN'um engano tão doce e deleitoso,\nQu'em qu'outro amante fosse mais ditoso\nNão valiam mil glórias um tormento.\n\nVendo-me possuir tal pensamento,\nDe nenhuma riqueza era invejoso;\nVivia bem, de nada receoso,\nCom doce amor e doce sentimento.\n\nCobiçosa a Fortuna, me tirou\nDeste meu tão contente e alegre estado;\nE passou-se este bem, que nunca fora:\n\nEm troco do qual bem só me deixou\nLembranças, que me matam cada hora,\nTrazendo-me à memória o bem passado."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCLXXIII, p. 137.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CED)\n\n**Notas sobre o texto.**\n\nA página ligada no Anexo do Wikisource (https://pt.wikisource.org/wiki/Eu_vivia_de_l%C3%A1grimas_isento) traz texto modernizado sem indicação de edição; aqui segue-se a ed. de 1843.\n\nPágina do Wikisource ainda não revisada (nível 1, importada do Projeto Gutenberg n.º 31509); texto conferido verso a verso com o Gutenberg; a última palavra do soneto está na página seguinte do Wikisource (https://pt.wikisource.org/wiki/P%C3%A1gina:Obras_completas_de_Luis_de_Cam%C3%B5es_II_(1843).djvu/212), por divisão automática do texto.\n\nVariantes na página do Anexo: v. 3 «que, em que outro amante»; v. 6 «de nenhüa riqueza era envejoso»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/P%C3%A1gina:Obras_completas_de_Luis_de_Cam%C3%B5es_II_(1843).djvu/211 e https://pt.wikisource.org/wiki/P%C3%A1gina:Obras_completas_de_Luis_de_Cam%C3%B5es_II_(1843).djvu/212"}]}},
"luis-de-camoes-soneto-indo-o-triste-pastor-todo-embebido": {"t":["Indo o triste pastor todo embebido\nNa sombra de seu doce pensamento,\nTais queixas espalhava ao leve vento,\nCo'um brando suspirar d'alma saído:\n\nA quem me queixarei, cego, perdido,\nPois nas pedras não acho sentimento?\nCom quem falo? A quem digo meu tormento?\nQue onde mais chamo, sou menos ouvido.\n\nÓ bela Ninfa, porque não respondes?\nPorque o olhar-me tanto m'encareces?\nPorque queres que sempre me querele?\n\nEu quanto mais te busco, mais te escondes!\nQuanto mais mal me vês, mais te endureces!\nAssim que co'o mal cresce a causa dele."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCLXXIV, p. 138.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página ligada no Anexo do Wikisource (https://pt.wikisource.org/wiki/Indo_o_triste_pastor_todo_embebido) traz texto modernizado sem indicação de edição; aqui segue-se a ed. de 1843.\n\nPágina do Wikisource ainda não revisada (nível 1, importada do Projeto Gutenberg n.º 31509); texto conferido verso a verso com o Gutenberg.\n\nVariantes na página do Anexo: v. 4 «cum brando suspirar da alma saído»; v. 12 «te vejo»; v. 14 «Assi que co mal»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/P%C3%A1gina:Obras_completas_de_Luis_de_Cam%C3%B5es_II_(1843).djvu/212"}]}},
"luis-de-camoes-soneto-dizei-senhora-da-beleza-ideia": {"t":["Dizei, Senhora, da beleza ideia,\nPara fazerdes esse áureo crino,\nOnde fostes buscar esse ouro fino?\nDe qu'escondida mina ou de que veia?\n\nDos vossos olhos essa luz Febeia,\nEsse respeito, de um Império dino?\nSe o alcançastes com saber divino,\nSe com encantamentos de Medeia?\n\nDe qu'escondidas conchas escolhestes\nAs perlas preciosas Orientais,\nQue falando mostrais no doce riso?\n\nPois vos formastes tal, como quisestes,\nVigiai-vos de vós, não vos vejais,\nFugi das fontes; lembre-vos Narciso."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCLXXV, p. 138.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nPágina do Wikisource não revista (texto importado do Projeto Gutenberg n.º 31509, que reproduz esta edição); conferido com a página principal do Wikisource, que traz texto modernizado de outra edição, com variantes.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Página:Obras_completas_de_Luis_de_Camões_II_(1843).djvu/212"}]}},
"luis-de-camoes-soneto-na-ribeira-do-eufrates-assentado": {"t":["Na ribeira do Eufrates assentado,\nDiscorrendo me achei pela memória\nAquele breve bem, aquela glória,\nQue em ti, doce Sião, tinha passado.\n\nDa causa de meus males perguntado\nMe foi: Como não cantas a história\nDe teu passado bem, e da vitória\nQue sempre de teu mal hás alcançado?\n\nNão sabes, que a quem canta se lhe esquece\nO mal, inda que grave e rigoroso?\nCanta pois, e não chores dessa sorte.\n\nRespondi com suspiros: Quando crece\nA muita saudade, o piedoso\nRemédio é não cantar, senão a morte."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCLXXVI, p. 139.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página ligada no Anexo do Wikisource (https://pt.wikisource.org/wiki/Na_ribeira_do_Eufrates_assentado) traz texto modernizado sem indicação de edição; aqui segue-se a ed. de 1843.\n\nPágina do Wikisource ainda não revisada (nível 1, importada do Projeto Gutenberg n.º 31509); texto conferido verso a verso com o Gutenberg.\n\nVariantes na página do Anexo: v. 12 «Respondo com suspiros: Quando cresce»; v. 13 «piadoso»\n\n«crece» (fonte) mantido: forma antiga de «cresce»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/P%C3%A1gina:Obras_completas_de_Luis_de_Cam%C3%B5es_II_(1843).djvu/213"}]}},
"luis-de-camoes-soneto-chorai-ninfas-os-fados-poderosos": {"t":["Chorai, Ninfas, os fados poderosos\nDaquela soberana formosura.\nOnde foram parar? na sepultura?\nAqueles Reais olhos graciosos?\n\nOh bens do mundo falsos e enganosos!\nQue mágoas para ouvir! Que tal figura\nJaza sem resplandor na terra dura\nCom tal rosto e cabelos tão formosos!\n\nDas outras que será! pois poder teve\nA morte sobre cousa tanto bela,\nQue ela eclipsava a luz do claro dia.\n\nMas o mundo não era digno dela,\nPor isso mais na terra não esteve,\nAo céu subiu, que já se lhe devia."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCLXXVII, p. 139.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\nPágina do Wikisource não revista (texto importado do Projeto Gutenberg n.º 31509, que reproduz esta edição); conferido com a página principal do Wikisource, que traz texto modernizado de outra edição, com variantes.\n\nO texto modernizado do Wikisource traz «fermosura», «rostro»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Página:Obras_completas_de_Luis_de_Camões_II_(1843).djvu/213"}]}},
"luis-de-camoes-soneto-doce-sonho-suave-e-soberano": {"t":["Doce sonho, suave e soberano,\nSe por mais longo tempo me durara!\nAh quem de sonho tal nunca acordara,\nPois havia de ver tal desengano!\n\nAh deleitoso bem! ah doce engano!\nSe por mais largo espaço me enganara!\nSe então a vida mísera acabara,\nDe alegria e prazer morrera ufano.\n\nDitoso, não estando em mi, pois tive\nDormindo o que acordado ter quisera.\nOlhai com que me paga meu destino!\n\nEnfim, fora de mim ditoso estive.\nEm mentiras ter dita razão era,\nPois sempre nas verdades fui mofino."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCLXXIX, p. 140.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nPágina do Wikisource não revista (texto importado do Projeto Gutenberg n.º 31509, que reproduz esta edição); conferido com a página principal do Wikisource, que traz texto modernizado de outra edição, com variantes.\n\nA última palavra («mofino.») está na página seguinte.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Página:Obras_completas_de_Luis_de_Camões_II_(1843).djvu/214"}]}},
"luis-de-camoes-soneto-diana-prateada-esclarecida": {"t":["Diana prateada, esclarecida\nCom a luz que do claro Febo ardente,\nPor ser de natureza transparente,\nEm si, como em espelho, reluzia,\n\nCem mil milhões de graças lhe influía,\nQuando me apareceu o excelente\nRaio de vosso aspecto, diferente\nEm graça e em amor do que soía.\n\nEu vendo-me tão cheio de favores,\nE tão propínquo a ser de todo vosso,\nLouvei a hora clara, e a noite escura,\n\nPois nela destes cor a meus amores:\nDonde colijo claro que não posso\nDe dia para vós já ter ventura."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCLXXX, p. 141.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE, com o v. 1 fora da rima)\n\n**Notas sobre o texto.**\n\nPágina do Wikisource não revista (texto importado do Projeto Gutenberg n.º 31509, que reproduz esta edição); conferido com a página principal do Wikisource, que traz texto modernizado de outra edição, com variantes.\n\n«esclarecida» (assim também no índice da ed. de 1843) quebra a rima em -ia; outras edições: «esclarecia»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Página:Obras_completas_de_Luis_de_Camões_II_(1843).djvu/215"}]}},
"luis-de-camoes-soneto-enquanto-febo-os-montes-acendia": {"t":["Enquanto Febo os montes acendia\nDo céu com luminosa claridade,\nPor conservar ilesa a castidade\nNa caça o tempo Délia despendia.\n\nVênus, qu'então de furto descendia\nPor cativar de Anquises a vontade,\nVendo Diana em tanta honestidade,\nQuase zombando dela, lhe dizia:\n\nTu vás com tuas redes na espessura\nOs fugitivos cervos enredando;\nMas as minhas enredam o sentido.\n\nMelhor é (respondia a deusa pura)\nNas redes leves cervos ir tomando,\nQue tomar-te a ti nelas teu marido."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCLXXXI, p. 141.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nPágina do Wikisource não revista (texto importado do Projeto Gutenberg n.º 31509, que reproduz esta edição); conferido com a página principal do Wikisource, que traz texto modernizado de outra edição, com variantes.\n\n«vás» (= vais) mantido.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Página:Obras_completas_de_Luis_de_Camões_II_(1843).djvu/215"}]}},
"luis-de-camoes-soneto-n-um-tao-alto-lugar-de-tanto-preco": {"t":["N'um tão alto lugar, de tanto preço,\nEste meu pensamento posto vejo,\nQue desfalece nele inda o desejo,\nVendo quanto por mi o desmereço.\n\nQuando esta tal baixeza em mi conheço,\nAcho que cuidar nele é grão despejo,\nE que morrer por ele me é sobejo\nE mor bem para mi, do que mereço.\n\nO mais que natural merecimento\nDe quem me causa um mal tão duro e forte,\nO faz que vá crescendo de hora em hora.\n\nMas eu não deixarei meu pensamento,\nPorque inda qu'este mal me causa a morte,\nUn bel morir tutta la vita onora."],"e":{"apresentacao":"**Publicação.** Obras completas de Luis de Camões, t. II (1843), Sonetos, CCLXXXII, p. 142.\n\n**Ortografia.** Atualizada (fonte: ed. Barreto Feio e Monteiro, t. II, 1843)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página ligada no Anexo do Wikisource (https://pt.wikisource.org/wiki/Num_t%C3%A3o_alto_lugar,_de_tanto_pre%C3%A7o) traz texto modernizado sem indicação de edição; aqui segue-se a ed. de 1843.\n\nV. 4: a ed. de 1843 (e o Gutenberg) imprime «par mi», erro tipográfico evidente por «por mi»; corrigido só no texto atualizado.\n\nV. 14: verso de Petrarca em italiano («Un bel morir tutta la vita honora»; grafia italiana atual «onora»)\n\nVariantes na página do Anexo: v. 11 «crecendo»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/P%C3%A1gina:Obras_completas_de_Luis_de_Cam%C3%B5es_II_(1843).djvu/216"}]}},
"luis-de-camoes-soneto-a-romana-populonia-perguntava": {"t":["À romana Populônia perguntava\num certo curioso e não prudente\npor que a alimária comumente\nem tempo certo do ano se juntava;\n\na qual, como discreta e que cuidava\nem repostas ser suma e eminente,\ncom ũa só palavra, claramente,\nrespondeu, e mostrou com quem folgava:\n\n«Bestas são,» dá a entender, «que não entendem\nquão grande suavidade se encerra\nna cópula himeneia e ajuntamento.\n\nMas mores bestas são os que pretendem\nbuscar contentamento à carne e à terra\ndeixando a alma prestes ao tormento»."],"e":{"apresentacao":"**Publicação.** Sonetos (texto do Wikisource, edição não identificada)\n\n**Ortografia.** Atualizada (fonte: texto modernizado do Wikisource, edição não identificada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nTexto do Wikisource sem indicação de edição, já em ortografia moderna (portuguesa), com formas antigas preservadas; este soneto não está no t. II da ed. de 1843 (Barreto Feio e Monteiro)\n\n«comummente» atualizado para «comumente»; «porque» interrogativo indireto atualizado para «por que»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/À_romana_Populónia_perguntava"}]}},
"luis-de-camoes-soneto-a-ti-senhor-a-quem-as-sacras-musas": {"t":["A ti, Senhor, a quem as sacras Musas\nnutrem e cibam de poção divina\n(não as da fonte Délia cabalina,\nque são Medeias, Circes e Medusas,\n\nmas aquelas, em cujo peito, infusas\nas leis estão, que a lei da Graça ensina,\nbeninas no amor e na doutrina\ne não soberbas, cegas e confusas),\n\neste pequeno parto, produzido\nde meu saber e fraco entendimento,\nũa vontade grande te oferece.\n\nSe for de ti notado de atrevido,\ndaqui peço perdão do atrevimento,\no qual esta vontade te merece."],"e":{"apresentacao":"**Publicação.** Sonetos (texto do Wikisource, edição não identificada)\n\n**Ortografia.** Atualizada (fonte: texto modernizado do Wikisource, edição não identificada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nTexto do Wikisource sem indicação de edição, já em ortografia moderna (portuguesa), com formas antigas preservadas; este soneto não está no t. II da ed. de 1843 (Barreto Feio e Monteiro)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/A_ti,_Senhor,_a_quem_as_sacras_Musas"}]}},
"luis-de-camoes-soneto-aqueles-claros-olhos-que-chorando": {"t":["Aqueles claros olhos que chorando\nficavam, quando deles me partia,\nagora que farão? Quem mo diria?\nSe porventura estarão em mim cuidando?\n\nSe terão na memória, como ou quando\ndeles me vim tão longe de alegria?\nOu se estarão aquele alegre dia,\nque torne a vê-los, na alma figurando?\n\nSe contarão as horas e os momentos?\nSe acharão num momento muitos anos?\nSe falarão co as aves e cos ventos?\n\nOh! bem-aventurados fingimentos\nque, nesta ausência, tão doces enganos\nsabeis fazer aos tristes pensamentos!"],"e":{"apresentacao":"**Publicação.** Sonetos (texto do Wikisource, edição não identificada)\n\n**Ortografia.** Atualizada (fonte: texto modernizado do Wikisource, edição não identificada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC CDC)\n\n**Notas sobre o texto.**\n\nTexto do Wikisource sem indicação de edição, já em ortografia moderna (portuguesa), com formas antigas preservadas; este soneto não está no t. II da ed. de 1843 (Barreto Feio e Monteiro)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Aqueles_claros_olhos_que_chorando"}]}},
"luis-de-camoes-soneto-com-que-voz-chorarei-meu-triste-fado": {"t":["Com que voz chorarei meu triste fado,\nque em tão dura prisão me sepultou,\nque mor não seja a dor que me deixou\no tempo, de meu bem desenganado?\n\nMas chorar não se estima neste estado,\nonde suspirar nunca aproveitou;\ntriste quero viver, pois se mudou\nem tristeza a alegria do passado.\n\nAssi a vida passo descontente,\nao som nesta prisão do grilhão duro\nque lastima o pé que o sofre e sente!\n\nDe tanto mal a causa é amor puro,\ndevido a quem de mi tenho ausente\npor quem a vida, e bens dela, aventuro."],"e":{"apresentacao":"**Publicação.** Sonetos (texto do Wikisource, edição não identificada)\n\n**Ortografia.** Atualizada (fonte: texto modernizado do Wikisource, edição não identificada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nTexto do Wikisource sem indicação de edição, já em ortografia moderna (portuguesa), com formas antigas preservadas; este soneto não está no t. II da ed. de 1843 (Barreto Feio e Monteiro)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Com_que_voz_chorarei_meu_triste_fado"}]}},
"luis-de-camoes-soneto-com-voz-desordenada-sem-sentido": {"t":["Com voz desordenada, sem sentido,\ne com olhos de lágrimas cobertos,\nsoltava o peito em ásperos desertos\nentre um vale escuro, empedernido,\n\nSilvano triste, a quem endurecido\ntêm de uma bela Ninfa os desconcertos,\nperdendo a esperança dos incertos\nbens em que a Fortuna o há metido;\n\nmas, volto em si um pouco, perguntava\nasi por si o pastor; desta tristeza\nlevanta o coração já desmaiado\n\ne canta, como quem melhor se achava:\n«Não desmaies, esprito, na pobreza,\nque a fortuna à razão é mau treslado!»"],"e":{"apresentacao":"**Publicação.** Sonetos (texto do Wikisource, edição não identificada)\n\n**Ortografia.** Atualizada (fonte: texto modernizado do Wikisource, edição não identificada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nTexto do Wikisource sem indicação de edição, já em ortografia moderna (portuguesa), com formas antigas preservadas; este soneto não está no t. II da ed. de 1843 (Barreto Feio e Monteiro)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Com_voz_desordenada,_sem_sentido"}]}},
"luis-de-camoes-soneto-de-um-tao-felice-engenho-produzido": {"t":["::dedicatoria A D. Simão da Silveira, em resposta de outro seu, pelos mesmos consoantes, mandando-lhe perguntar quem fora o primeiro poeta que fizera sonetos\n\nDe um tão felice engenho, produzido\nde outro, que o claro Sol não viu maior,\né trazer cousas altas no sentido,\ntodas dinas de espanto e de louvor.\n\nMuseu foi antiquíssimo escritor,\nfilósofo e poeta conhecido,\ndiscípulo do Músico amador\nque co som teve o Inferno suspendido.\n\nEste pôde abalar o monte mudo,\ncantando aquele mal, que eu já passei,\ndo mancebo de Abido mal sisudo.\n\nAgora contam já (segundo achei),\nTasso, e o nosso Boscão, que disse tudo\ndos segredos que move o cego Rei."],"e":{"apresentacao":"**Publicação.** Sonetos (texto do Wikisource, edição não identificada)\n\n**Ortografia.** Atualizada (fonte: texto modernizado do Wikisource, edição não identificada)\n\n**Forma.** Soneto (decassílabos; rimas ABAB BABA CDC DCD)\n\n**Notas sobre o texto.**\n\nTexto do Wikisource sem indicação de edição, já em ortografia moderna (portuguesa), com formas antigas preservadas; este soneto não está no t. II da ed. de 1843 (Barreto Feio e Monteiro)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/A_D._Simão_da_Silveira"}]}},
"luis-de-camoes-soneto-deixando-o-doce-fato-e-a-cabana": {"t":["Deixando o doce fato e a cabana,\nHilário pastor por ũa serra alçada\ndesta arte se aqueixava em voz irada\nda fermosa pastora Terciana:\n\n«Nem tu és nascida de gente humana,\nnem foste em ventre de mulher gerada;\nmas antre as duras feras és criada,\nmamando o leite algũa tigre hircana.\n\nSe em ti houvera algum modo de sentido,\nmeu mal movera a aspereza tua\ne abrandara teu peito endurecido.\n\nMas creio que mostrando a ira sua,\nDeus, pera ser das gentes mais temido,\nfez a mim desditoso e a ti crua.»"],"e":{"apresentacao":"**Publicação.** Sonetos (texto do Wikisource, edição não identificada)\n\n**Ortografia.** Atualizada (fonte: texto modernizado do Wikisource, edição não identificada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nTexto do Wikisource sem indicação de edição, já em ortografia moderna (portuguesa), com formas antigas preservadas; este soneto não está no t. II da ed. de 1843 (Barreto Feio e Monteiro)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Deixando_o_doce_fato_e_a_cabana"}]}},
"luis-de-camoes-soneto-descalco-e-sem-chapeu-apolo-louro": {"t":["Descalço e sem chapéu Apolo louro,\ndos mais vestidos bem ataviado,\num dia o vi vir tão namorado\nda lira, que nas mãos trazia, de ouro...\n\nDizendo alegre vinha: «Ó meu tesouro,\nvida e tempo nas músicas gastado,\ncom um defeito is desconcertado\nque, sendo português, me fazeis mouro.\n\nNo trajo digo só, porque é costume\nna minha gente ser o trajo inteiro,\nnão em parte; mas em tudo se resume.\n\nDais-me pelote e capa, sem sombreiro;\nsem calças me subis num alto cume,\naonde o vento temo ser ligeiro»."],"e":{"apresentacao":"**Publicação.** Sonetos (texto do Wikisource, edição não identificada)\n\n**Ortografia.** Atualizada (fonte: texto modernizado do Wikisource, edição não identificada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nTexto do Wikisource sem indicação de edição, já em ortografia moderna (portuguesa), com formas antigas preservadas; este soneto não está no t. II da ed. de 1843 (Barreto Feio e Monteiro)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Descalço_e_sem_chapéu_Apolo_louro"}]}},
"luis-de-camoes-soneto-el-vaso-reluciente-y-cristalino": {"t":["El vaso reluciente y cristalino,\nde Ángeles agua clara y olorosa,\nde blanca seda ornado y fresca rosa,\nligado con cabellos de oro fino,\n\nbien claro parecía el don divino\nlabrado por la mano artificiosa\nde aquella blanca Ninfa, graciosa\nmás que el rubio lucero matutino.\n\nNel vaso vuestro cuerpo se afigura,\nraxado de los blancos miembros bellos,\ny en el agua vuestra ánima pura.\n\nLa seda es la blancura, y los cabellos\nson las prisiones y la ligadura\ncon que mi libertad fue asida dellos."],"e":{"apresentacao":"**Publicação.** Sonetos (texto do Wikisource, edição não identificada)\n\n**Ortografia.** Castelhano, como na fonte (texto do Wikisource, edição não identificada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nSoneto em castelhano.\n\nTexto do Wikisource sem indicação de edição, já em ortografia moderna (portuguesa), com formas antigas preservadas; este soneto não está no t. II da ed. de 1843 (Barreto Feio e Monteiro)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/El_vaso_reluciente_y_cristalino"}]}},
"luis-de-camoes-soneto-em-um-batel-que-com-doce-meneio": {"t":["Em um batel que com doce meneio\no aurífero Tejo dividia,\nvi belas damas ou, melhor diria,\nbelas estrelas, e um Sol no meio.\n\nAs delicadas filhas de Nereio,\ncom mil cordas de doce harmonia,\niam amarrando a bela companhia\nque, se eu não erro, por honrá-las veio.\n\nÓ fermosas Nereidas que, cantando,\nlograis aquela vista tão serena\nque a vida, em tantos males, quer trazer-me:\n\ndizei-lhe que olhe que se vai passando\no curto tempo e, a tão longa pena,\no espírito é pronto, a carne enferma."],"e":{"apresentacao":"**Publicação.** Sonetos (texto do Wikisource, edição não identificada)\n\n**Ortografia.** Atualizada (fonte: texto modernizado do Wikisource, edição não identificada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDF)\n\n**Notas sobre o texto.**\n\nTexto do Wikisource sem indicação de edição, já em ortografia moderna (portuguesa), com formas antigas preservadas; este soneto não está no t. II da ed. de 1843 (Barreto Feio e Monteiro)\n\nVv. 11 e 14: «trazer-me» / «enferma», rima imperfeita no texto.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Em_um_batel_que_com_doce_meneio"}]}},
"luis-de-camoes-soneto-ja-tempo-foi-que-meus-olhos-folgavam": {"t":["Já tempo foi que meus olhos folgavam\nde ver os verdes campos graciosos;\ntempo foi já também que os sonorosos\nribeiros meus ouvidos recreavam.\n\nFoi tempo que nos bosques me alegravam\nos cantares das aves saudosos,\nos freixos e altos álamos umbrosos\ncujos ramos por cima se ajuntavam.\n\nPermanecer não pude em tal folgança;\nnão me pôde durar esta alegria,\nnão quis este meu bem ter segurança;\n\nainda neste tempo eu não sentia\ndo fero Amor a força e a mudança,\nos laços e as prisões com que prendia."],"e":{"apresentacao":"**Publicação.** Sonetos (Wikisource, texto sem indicação de edição)\n\n**Ortografia.** Atualizada (fonte: texto já modernizado do Wikisource, grafia portuguesa)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nNão localizado na ed. de 1843 nem no vol. II da ed. Juromenha; texto sem conferência em outra fonte.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/J%C3%A1_tempo_foi_que_meus_olhos_folgavam"}]}},
"luis-de-camoes-soneto-memoria-de-meu-bem-cortado-em-flores": {"t":["Memória de meu bem, cortado em flores\npor ordem de meus tristes e maus Fados,\ndeixai-me descansar com meus cuidados\nnesta inquietação de meus amores.\n\nBasta-me o mal presente e os temores\ndos sucessos, que espero, infortunados;\nsem que venham, de novo, bens passados\nafrontar meu repouso com suas dores.\n\nPerdi nũa hora quanto em termos\ntão vagarosos e largos alcancei;\ndeixai-me, pois, lembranças desta glória.\n\nCumpre acabe a vida nestes ermos,\nque neles com meu mal acabarei\nmil vidas, não ũa só, dura memória!"],"e":{"apresentacao":"**Publicação.** Sonetos (Wikisource, texto sem indicação de edição; na ed. Juromenha, vol. II, soneto CCCXXXVII)\n\n**Ortografia.** Atualizada (fonte: texto já modernizado do Wikisource, grafia portuguesa)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nV. 9 («Perdi nũa hora quanto em termos», 8 sílabas) e v. 10 («tão vagarosos e largos alcancei», 11) fogem ao decassílabo também em Juromenha; edições modernas suprem «[tudo]» no v. 9; soneto de texto duvidoso.\n\nVariantes em Juromenha: v. 13 «Porque, nelles com meu mal acabarei»; v. 14 «não huma só»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Mem%C3%B3ria_de_meu_bem,_cortado_em_flores"}]}},
"luis-de-camoes-soneto-memorias-ofendidas-que-um-so-dia": {"t":["Memórias ofendidas que um só dia\nme não deixais em paz o pensamento,\nnão me daneis o gosto do tormento,\nque quem vos ofendeu vos defendia.\n\nQue me quereis? Olhai que se injuria\nconvosco o delicado sentimento\nque me ficou do eterno apartamento\nde quem já tem desfeita a morte fria.\n\nDeixaram-me co a mágoa das ofensas;\nlevaram um remédio só que tinha.\nQuem irá vencer a pena que alma sente,\n\nonde achará do dano as recompensas,\nse ainda de ser triste a dita minha\nme não deixa um momento ser contente?"],"e":{"apresentacao":"**Publicação.** Sonetos (Wikisource, texto sem indicação de edição; na ed. Juromenha, vol. II, soneto CCCXXXIV)\n\n**Ortografia.** Atualizada (fonte: texto já modernizado do Wikisource, grafia portuguesa)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nVariantes em Juromenha: v. 4 «Que quem vos offende vos deffendia»; v. 8 «De quem tem ja desfeita»; v. 9 «Deixarão-me com a magoa»; v. 10 «Levarão hum remedio que só tinha»; v. 11 «que a alma sente»; v. 13 «Que ainda»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Mem%C3%B3rias_ofendidas_que_um_s%C3%B3_dia"}]}},
"luis-de-camoes-soneto-o-dia-em-que-eu-nasci-morra-e-pereca": {"t":["O dia em que eu nasci, morra e pereça,\nNão o queira jamais o tempo dar,\nNão torne mais ao mundo e, se tornar,\nEclipse nesse passo o sol padeça.\n\nA luz lhe falte, o sol se lhe escureça,\nMostre o mundo sinais de se acabar,\nNasçam-lhe monstros, sangue chova o ar,\nA mãe ao próprio filho não conheça.\n\nAs pessoas pasmadas, de ignorantes,\nAs lágrimas no rosto, a cor perdida,\nCuidem que o mundo já se destruiu.\n\nÓ gente temerosa, não te espantes,\nQue este dia deitou ao mundo a vida\nMais desgraçada que jamais se viu!"],"e":{"apresentacao":"**Publicação.** Sonetos (Wikisource, texto sem indicação de edição; na ed. Juromenha, vol. II, soneto CCCXXXIX)\n\n**Ortografia.** Atualizada (fonte: texto já modernizado do Wikisource, grafia portuguesa)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nVariantes em Juromenha (vol. II): v. 1 «O dia, hora em que naci moura e pereça»; v. 5 «o sol se escureça»; no vol. I (ensaio biográfico) o v. 1 aparece como aqui.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/O_dia_em_que_eu_nasci,_morra_e_pere%C3%A7a"}]}},
"luis-de-camoes-soneto-o-gloriosa-cruz-o-vitorioso": {"t":["Ó gloriosa cruz, ó vitorioso\ntroféu, de despojos rodeado,\nó sinal escolhido e ordenado\npara remédio tão maravilhoso;\n\nó fonte viva de licor sagrado,\nem ti nosso mal todo foi curado!\nEm ti o Senhor, que forte era chamado,\nquis merecer o nome de piedoso.\n\nEm ti se acabou o tempo da vingança;\nem ti misericórdia assim floreça\ncomo despois do inverno a primavera.\n\nTodo o imigo ante ti desapareça.\nTu pudeste fazer tanta mudança\nem quem nunca deixou de ser quem era."],"e":{"apresentacao":"**Publicação.** Sonetos (Wikisource, texto sem indicação de edição; na ed. Juromenha, vol. II, soneto CCCLI)\n\n**Ortografia.** Atualizada (fonte: texto já modernizado do Wikisource, grafia portuguesa)\n\n**Forma.** Soneto (decassílabos; rimas ABBA BBBA CDE DCE)\n\n**Notas sobre o texto.**\n\nV. 2: «troféu» conta 3 sílabas (tro-fé-u; Juromenha: «Tropheo de despojos rodeado»), o que completa o decassílabo; a 2.ª quadra só tem a rima -ado nos três primeiros versos (esquema irregular); soneto de autoria discutida.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/%C3%93_gloriosa_cruz,_%C3%B3_vitorioso"}]}},
"luis-de-camoes-soneto-o-tempo-acaba-o-ano-o-mes-e-a-hora": {"t":["O tempo acaba o ano, o mês e a hora,\nA força, a arte, a manha, a fortaleza;\nO tempo acaba a fama e a riqueza,\nO tempo o mesmo tempo de si chora.\n\nO tempo busca e acaba onde mora\nQualquer ingratidão, qualquer dureza;\nMas não pode acabar minha tristeza,\nEnquanto não quiserdes vós, Senhora.\n\nO tempo o claro dia torna escuro,\nE o mais ledo prazer em choro triste;\nO tempo, a tempestade em grã bonança.\n\nMas de abrandar o tempo estou seguro\nO peito de diamante, onde consiste\nA pena e o prazer desta esperança."],"e":{"apresentacao":"**Publicação.** Sonetos (Wikisource, texto sem indicação de edição; na ed. Juromenha, vol. II, soneto CCXCVI)\n\n**Ortografia.** Atualizada (fonte: texto já modernizado do Wikisource, grafia portuguesa)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nV. 5: Juromenha traz «O tempo busca, e acaba o onde mora» (com «o onde»)\n\nVariante em Juromenha: v. 11 «grão bonança»","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/O_tempo_acaba_o_ano,_o_m%C3%AAs_e_a_hora"}]}},
"luis-de-camoes-soneto-olhos-fermosos-em-quem-quis-natura": {"t":["Olhos fermosos, em quem quis Natura\nmostrar do seu poder altos sinais,\nse quiserdes saber quanto possais,\nvede-me a mim, que sou vossa feitura.\n\nPintada em mim se vê vossa figura;\nno que eu padeço retratada estais;\nque, se eu passo tormentos desiguais,\nmuito mais pode vossa fermosura.\n\nDe mim não quero mais que o meu desejo:\nser vosso; e só de ser vosso me arreio,\npor que o vosso penhor em mim se assele.\n\nNão me lembro de mim, quando vos vejo,\nnem do mundo; e não erro, porque creio\nque, em lembrar-me de vós, cumpro com ele."],"e":{"apresentacao":"**Publicação.** Sonetos (Wikisource, texto sem indicação de edição; na ed. Juromenha, vol. II, soneto CCC)\n\n**Ortografia.** Atualizada (fonte: texto já modernizado do Wikisource, grafia portuguesa)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nVariantes em Juromenha: v. 1 «Olhos formosos»; «mi» por «mim» nos v. 4, 5, 9, 11 e 12.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Olhos_fermosos,_em_quem_quis_Natura"}]}},
"luis-de-camoes-soneto-posto-me-tem-fortuna-em-tal-estado": {"t":["Posto me tem fortuna em tal estado,\nE tanto a seus pés me tem rendido!\nNão tenho que perder já, de perdido,\nNão tenho que mudar já, de mudado.\n\nTodo o bem para mim é acabado;\nDaqui dou o viver já por vivido;\nQue, aonde o mal é tão conhecido,\nTambém o viver mais será escusado.\n\nSe me basta querer, a morte quero,\nQue bem outra esperança não convém,\nE curarei um mal com outro mal.\n\nE pois do bem tão pouco bem espero,\nJá que o mal este só remédio tem,\nNão me culpem em querer remédio tal."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Posto_me_tem_fortuna_em_tal_estado"}]}},
"luis-de-camoes-soneto-pues-lagrimas-tratais-mis-ojos-tristes": {"t":["Pues lágrimas tratáis, mis ojos tristes,\ny en lágrimas pasáis la noche y día,\nmirad si es llanto este que os envía\naquella por quien vos tantas vertistes.\n\nSentid, mis ojos, bien esta que vistes,\ny si ella lo es, oh gran ventura mía!\npor muy bien empleadas las habría\nmil cuentos que por esta sola distes.\n\nMas una cosa mucho deseada,\naunque se vea cierta, no es creída;\ncuanto más esta, que me es enviada.\n\nPero digo que aunque sea fingida,\nque basta que por lágrima sea dada,\npor que sea por lágrima tenida."],"e":{"apresentacao":"**Publicação.** Sonetos (em castelhano); edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto em castelhano (endecassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.\n\nSoneto em castelhano; texto mantido igual nas duas versões.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Pues_lágrimas_tratáis,_mis_ojos_tristes"}]}},
"luis-de-camoes-soneto-qual-tem-a-borboleta-por-costume": {"t":["Qual tem a borboleta por costume,\nque, enlevada na luz da acesa vela,\ndando vai voltas mil, até que nela\nse queima agora, agora se consume;\n\ntal eu correndo vou ao vivo lume\ndesses olhos gentis, Aônia bela;\ne abraso-me, por mais que com cautela\nlivrar-me a parte racional presume.\n\nConheço o muito a que se atreve a vista,\no quanto se levanta o pensamento,\no como vou morrendo claramente.\n\nPorém, não quer Amor que lhe resista,\nnem a minha alma o quer; que em tal tormento,\nqual em glória maior, está contente."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.\n\nSoneto ausente dos 166 sonetos do texto-base de Costa Pimpão (Biblioteca Virtual do Estudante Brasileiro, USP); atribuição possivelmente duvidosa.\n\nA ed. de 1843 (t. II, CCLVII) traz o mesmo texto.\n\nA fonte grafa 'Aónia' (acento português); na versão atualizada, 'Aônia'.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Qual_tem_a_borboleta_por_costume"}]}},
"luis-de-camoes-soneto-quando-cuido-no-tempo-que-contente": {"t":["Quando cuido no tempo que, contente,\nVi as pérolas, neve, rosa e ouro,\nComo quem vê por sonhos um tesouro,\nParece tenho tudo aqui presente.\n\nMas tanto que se passa este acidente,\nE vejo o quão distante de vós mouro,\nTemo quanto imagino por agouro,\nPor que de imaginar também me ausente.\n\nJá foram dias em que por ventura\nVos vi, Senhora, se assi dizendo posso,\nCo coração seguro estar, sem medo;\n\nAgora, em tanto mal não me assegura\nA própria fantasia e nojo vosso:\nEu não posso entender este segredo!"],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.\n\nV10 tem 11 sílabas métricas também no texto-base de Costa Pimpão (\"Vos vi, Senhora (se, assi dizendo, posso\")","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quando_cuido_no_tempo_que,_contente"}]}},
"luis-de-camoes-soneto-quando-senhora-quis-amor-que-amasse": {"t":["Quando, Senhora, quis Amor que amasse\nessa grã perfeição e gentileza,\nlogo deu por sentença que a crueza\nem vosso peito amor acrescentasse.\n\nDeterminou que nada me apartasse:\nnem desfavor cruel, nem aspereza;\nmas que em minha raríssima firmeza\nvossa isenção cruel se executasse.\n\nE pois tendes aqui oferecida\nesta alma vossa a vosso sacrifício,\nacabai de fartar vossa vontade.\n\nNão lhe alargueis, Senhora, mais a vida;\nacabará morrendo em seu ofício,\nsua fé defendendo e lealdade."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quando,_Senhora,_quis_Amor_que_amasse"}]}},
"luis-de-camoes-soneto-que-gritos-sao-os-que-ouco-de-tristeza": {"t":["«Que gritos são os que ouço?» – «De tristeza».\n«Quem é a causa dela?» – «A morte só».\n«Tão grande mal nos fez?» – «Quebrou um nó».\n«Que nó? A quem atava?» – «A gentileza».\n\n«Era mais que fermosa?» – «Era de Alteza».\n«Desfez-se em ouro?» – «Não, em terra, em pó».\n«Também é como nós?» – «Também, mas só».\n«Que gemes?» – «De perder a tal Princesa».\n\n«Não vês que tudo é mundo?» – «Bem o entendo».\n«Pois não te agastes». – «Não mo sofre a alma».\n«Que te consola aqui?» – «Na vida vê-la».\n\n«Tão boa foi?» – «O reino o está dizendo».\n«Pois sabe que, se cá levou a palma,\nque lá terá também a palma dela»."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto dialogado (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.\n\nSoneto ausente dos 166 sonetos do texto-base de Costa Pimpão (Biblioteca Virtual do Estudante Brasileiro, USP); atribuição possivelmente duvidosa.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Que_gritos_são_os_que_ouço%3F_–_De_tristeza"}]}},
"luis-de-camoes-soneto-que-pode-ja-fazer-minha-ventura": {"t":["Que pode já fazer minha ventura\nque seja para meu contentamento?\nOu como fazer devo fundamento\nde cousa que o não tem, nem é segura?\n\nQue pena pode ser tão certa e dura\nque possa ser maior que meu tormento?\nOu como receará meu pensamento\nos males, se com eles mais se apura?\n\nComo quem se costuma de pequeno\ncom peçonha criar por mão ciente,\nda qual o uso já o tem seguro;\n\nassi de acostumado co veneno,\no uso de sofrer meu mal presente\nme faz não sentir já nada o futuro."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Que_pode_já_fazer_minha_ventura"}]}},
"luis-de-camoes-soneto-quem-quiser-ver-d-amor-ua-excelencia": {"t":["Quem quiser ver d'Amor ũa excelência\nonde sua fineza mais se apura,\natente onde me põe minha ventura,\npor ter de minha fé experiência.\n\nOnde lembranças mata a longa ausência,\nem temeroso mar, em guerra dura,\nali a saudade está segura,\nquando mor risco corre a paciência.\n\nMas ponha-me Fortuna e o duro Fado\nem nojo, morte, dano e perdição,\nou em sublime e próspera ventura;\n\nponha-me, enfim, em baixo ou alto estado;\nque até na dura morte me acharão\nna língua o nome, n'alma a vista pura."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDB CDB)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quem_quiser_ver_d'_Amor_ũa_excelência"}]}},
"luis-de-camoes-soneto-quem-vos-levou-de-mi-saudoso-estado": {"t":["Quem vos levou de mi, saudoso estado,\nque tanta sem-razão comigo usastes?\nQuem foi? Por quem tão presto me negastes,\nesquecido de todo o bem passado?\n\nTrocastes-me um descanso em um cuidado\ntão duro, tão cruel, qual me ordenastes;\na fé, que tínheis dado, me negastes,\nquando mais nela estava confiado.\n\nVivia sem receio deste mal;\nFortuna, que tem tudo a sua mercê,\namor com desamor me revolveu.\n\nBem sei que neste caso nada val,\nque, quem nasceu chorando, justo é\nque pague com chorar o que perdeu."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Quem_vos_levou_de_mi,_saudoso_estado"}]}},
"luis-de-camoes-soneto-razao-e-ja-que-minha-confianca": {"t":["Razão é já que minha confiança\nse desça de ũa falsa opinião;\nmas Amor não se rege por razão:\nnão posso perder logo a esperança.\n\nA vida, si; que ũa áspera mudança\nnão deixa viver tanto um coração.\nE eu na morte tenho a salvação,\nsi; mas quem a deseja não a alcança.\n\nForçado é logo que eu espere e viva.\nAh! dura lei de Amor, que não consente\nquietação nũa alma que é cativa!\n\nSe hei de viver, enfim, forçadamente,\npara que quero a glória fugitiva\nde ũa esperança vã que me atormente?"],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.\n\nO texto-base de Costa Pimpão (BVEB/USP) começa 'Tempo é já que minha confiança'; a ed. de 1843, 'Ja he tempo, ja, que minha confiança'.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Razão_é_já_que_minha_confiança"}]}},
"luis-de-camoes-soneto-se-a-fortuna-inquieta-e-mal-olhada": {"t":["Se a Fortuna inquieta e mal olhada,\nque a justa lei do Céu consigo infama,\na vida quieta, que ela mais desama,\nme concedera, honesta e repousada;\n\npudera ser que a Musa, alevantada\ncom luz de mais ardente e viva flama,\nfizera ao Tejo lá na pátria cama\nadormecer co som da lira amada.\n\nPorém, pois o destino trabalhoso,\nque me escurece a Musa fraca e lassa,\nlouvor de tanto preço não sustenta,\n\na vossa, de louvar-me pouco escassa,\noutro sujeito busque valeroso,\ntal qual em vós ao mundo se apresenta."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Se_a_Fortuna_inquieta_e_mal_olhada"}]}},
"luis-de-camoes-soneto-se-a-ninguem-tratais-com-desamor": {"t":["Se a ninguém tratais com desamor,\nantes a todos tendes afeição,\ne se a todos mostrais um coração\ncheio de mansidão, cheio de amor;\n\ndesde hoje me tratai com desfavor,\nmostrai-me um ódio esquivo, ũa isenção;\npoderei acabar de crer então\nque somente a mi me dais favor.\n\nQue, se tratais a todos brandamente,\nclaro é que aquele é só favorecido\na quem mostrais irado o continente.\n\nMal poderei eu ser de vós querido,\nse tendes outro amor na alma presente,\nque amor é um, não pode ser partido."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.\n\nSoneto ausente dos 166 sonetos do texto-base de Costa Pimpão (Biblioteca Virtual do Estudante Brasileiro, USP); atribuição possivelmente duvidosa.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Se_a_ninguém_tratais_com_desamor"}]}},
"luis-de-camoes-soneto-se-cuidasse-que-nesse-peito-isento": {"t":["Se cuidasse que nesse peito isento\ninda algum tempo minha grande dor\nvos fizesse sentir, não digo amor,\nsenão um piadoso sentimento;\n\ntamanho fora meu contentamento\nque o mal que por vós passo, inda que mor,\nsem pena, sem cuidado, sem temor,\nsem queixumes passara este tormento.\n\nPorém como, Senhora, já conheço\na vossa condição isenta e dura\nno pouco que sentis o que padeço,\n\nnão há i senão queixar-me da Ventura\npois, em lugar do bem que vos mereço,\nmales em tanto mal me dais por cura."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.\n\nSoneto ausente dos 166 sonetos do texto-base de Costa Pimpão (Biblioteca Virtual do Estudante Brasileiro, USP); atribuição possivelmente duvidosa.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Se_cuidasse_que_nesse_peito_isento"}]}},
"luis-de-camoes-soneto-se-de-vosso-fermoso-e-lindo-gesto": {"t":["Se de vosso fermoso e lindo gesto\nnasceram lindas flores para os olhos,\nque para o peito são duros abrolhos,\nem mim se vê mui claro e manifesto.\n\nPois vossa fermosura e vulto honesto,\nem os ver, de boninas vi mil molhos;\nmas, se meu coração tivera antolhos,\nnão vira em vós seu dano o mal funesto;\n\num mal visto por bem, um bem tristonho,\nque me traz elevado o pensamento\nem mil, porém diversas, fantasias,\n\nnas quais eu sempre ando, e sempre sonho.\nE vós não cuidais mais que em meu tormento,\nem que fundais as vossas alegrias."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Se_de_vosso_fermoso_e_lindo_gesto"}]}},
"luis-de-camoes-soneto-se-em-mi-o-alma-vive-mais-lembranca": {"t":["Se em mi, ó Alma, vive mais lembrança\nque aquela só da glória de querer-vos,\neu perca todo o bem que logro em ver-vos,\ne de ver-vos também toda a esperança.\n\nVeja-se em mi tão rústica esquivança\nque possa indino ser de conhecer-vos;\ne, quando em mor empenho de aprazer-vos,\nvos ofenda, se em mi houver mudança.\n\nConfirmado estou já nesta certeza;\nexamine-me vossa crueldade,\nexprimente-se em mi vossa dureza.\n\nConhecei já de mi tanta verdade,\npois, em penhor e fé desta pureza,\ntributo vos fiz ser o que é vontade."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.\n\nSoneto ausente dos 166 sonetos do texto-base de Costa Pimpão (Biblioteca Virtual do Estudante Brasileiro, USP); atribuição possivelmente duvidosa.\n\nA ed. de 1843 (t. II, CCLV) traz o mesmo texto, com \"mim\" e \"indigno\"","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Se_em_mi,_ó_Alma,_vive_mais_lembrança"}]}},
"luis-de-camoes-soneto-se-lagrimas-choradas-de-verdade": {"t":["Se lágrimas choradas de verdade\nabrandar podem um coração duro,\nporque as minhas que nascem d'um amor puro\nvos não movem, Senhora, a piadade?\n\nPois por vós perdi a liberdade,\ne da vida não estou inda seguro,\nrompei de desamor tão forte muro\ne não useis de vossa crueldade.\n\nA males nunca vistos dai já fim,\ne não queirais ser, sendo fermosa,\nhavida por cruel e homicida.\n\nPera vós vos queria eu piadosa;\nque de o nunca serdes pera mim\na esperança tenho já perdida."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE DCE)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.\n\nSoneto ausente do texto-base de Costa Pimpão consultado; a ed. de 1843 (t. II, CCLII) traz outra versão, com tercetos diferentes.\n\nVersos de medida defeituosa nesta lição: v5 (9 sílabas; 1843: \"Por vós perdi, Senhora, a liberdade\"), v6 (11) e v10 (9); texto duvidoso para estudo de ritmo.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Se_lágrimas_choradas_de_verdade"}]}},
"luis-de-camoes-soneto-se-os-capitaes-antigos-colocados": {"t":["Se os capitães antigos colocados\nnaqueles triunfos altos de vitória\nferiram nas orelhas vossa história,\nde vergonha e temor foram pasmados.\n\nPor terra logo todos derribados\ntroféus, fama e sua grão memória,\ndando lugar ao louvor vosso e glória,\nque sós no mundo fossem celebrados.\n\nNa Antiguidade levam-vos vantagem\nque está de errores cheia em toda parte,\ncomo se mostra bem no que temos visto.\n\nVós, nas obras, feitos e linhagem\nque na milícia sois o mesmo Marte\ne em virtudes cumpris a lei de Cristo.\n\n(De Dom Constantino cante o universo,\nse bastar língua, ou prosa, engenho, ou verso.)"],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto com estrambote (decassílabos; rimas ABBA ABBA CDE CDE FF)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.\n\nOs dois últimos versos, entre parênteses na fonte, formam um dístico acrescentado ao soneto (estrambote)","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Se_os_capitães_antigos_colocados"}]}},
"luis-de-camoes-soneto-sempre-cruel-senhora-receei": {"t":["Sempre, cruel Senhora, receei,\nmedindo vossa grã desconfiança,\nque desse em desamor vossa tardança,\ne que me perdesse eu, pois vos amei.\n\nPerca-se, enfim, já tudo o que esperei,\npois noutro amor já tendes esperança.\nTão patente será vossa mudança\nquanto eu encobri sempre o que vos dei.\n\nDei-vos a alma, a vida e o sentido;\nde tudo o que em mim há vos fiz senhora.\nPrometeis e negais o mesmo Amor.\n\nAgora tal estou que, de perdido,\nnão sei por onde vou; mas algum'hora\nvos dará tal lembrança grande dor."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.\n\nA fonte traz \"algü' hora\" (ü por ũ); atualizado para \"algum'hora\", como na ed. de 1843.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Sempre,_cruel_Senhora,_receei"}]}},
"luis-de-camoes-soneto-senhora-ja-dest-alma-perdoai": {"t":["Senhora já dest'alma, perdoai\nde um vencido de Amor os desatinos;\ne sejam vossos olhos tão beninos\ncom este puro amor, que d'alma sai.\n\nA minha pura fé somente olhai,\ne vede meus extremos se são finos;\ne se de algũa pena forem dinos,\nem mim, Senhora minha, vos vingai.\n\nNão seja a dor, que abrasa o triste peito,\ncausa por onde pene o coração,\nque tanto em firme amor vos é sujeito.\n\nGuardai-vos do que alguns, Dama, dirão;\nque, sendo raro em tudo vosso objeito,\npossa morar em vós ingratidão."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.\n\nA fonte traz 'algüa' (ü por ũ); atualizado para 'algũa'.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Senhora_já_dest'_alma,_perdoai"}]}},
"luis-de-camoes-soneto-sustenta-meu-viver-ua-esperanca": {"t":["Sustenta meu viver ũa esperança\nderivada de um bem tão desejado\nque, quando nela estou mais confiado,\nmor dúvida me põe qualquer mudança.\n\nE quando inda este bem na mor pujança\nde seus gostos me tem mais enlevado,\nme atormenta então ver eu que, alcançado\nserá por quem de vós não tem lembrança.\n\nAssi que nestas redes enlaçado,\na penas dou a vida, sustentando\nũa nova matéria a meu cuidado;\n\nsuspiros d'alma tristes arrancando,\ndos silvos de ũa pedra acompanhado,\nestou matérias tristes lamentando."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA BCB CBC)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Sustenta_meu_viver_ũa_esperança"}]}},
"luis-de-camoes-soneto-todas-as-almas-tristes-se-mostravam": {"t":["Todas as almas tristes se mostravam\npela piadade do Feitor divino,\nonde, ante o seu aspecto benino,\no devido tributo lhe pagavam.\n\nMeus sentidos então livres estavam\n(que até i foi costume o seu destino),\nquando uns olhos, de que eu não era dino,\na furto da Razão me salteavam.\n\nA nova vista me cegou de todo;\nnasceu do descostume a estranheza\nda suave e angélica presença.\n\nPera remediar-me não há i modo?\nOh! porque fez a humana natureza\nentre os nascidos tanta diferença?"],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDE CDE)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.\n\nSoneto ausente dos 166 sonetos do texto-base de Costa Pimpão (Biblioteca Virtual do Estudante Brasileiro, USP); atribuição possivelmente duvidosa.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Todas_as_almas_tristes_se_mostravam"}]}},
"luis-de-camoes-soneto-vai-me-gastando-amor-e-um-pensamento": {"t":["Vai-me gastando Amor e um pensamento\nque me inclina a seguir meus próprios danos,\na esperança, o ser, o gosto e os anos,\nque para mi são mil cada momento.\n\nOs suspiros que em vão entrego ao vento\npaga-mos quem mos causa em desenganos;\ne, se quero fingir novos enganos,\nnão mos quer consentir o entendimento.\n\nSe pretendo mostrar quanto padeço,\nfalta-me a voz, o alento e o sentido;\ne a triste vida, não, porque a aborreço.\n\nO peito em vivas chamas convertido,\nenfim, mostre seu mal, pois já confesso\nque nem dizer se pode nem ser crido."],"e":{"apresentacao":"**Publicação.** Sonetos; edição não indicada na fonte.\n\n**Ortografia.** Atualizada (fonte: texto já modernizado da página do Wikisource, sem edição indicada)\n\n**Forma.** Soneto (decassílabos; rimas ABBA ABBA CDC DCD)\n\n**Notas sobre o texto.**\n\nA página do Wikisource não indica a edição; texto já em grafia moderna, com formas antigas preservadas.\n\nSoneto ausente dos 166 sonetos do texto-base de Costa Pimpão (Biblioteca Virtual do Estudante Brasileiro, USP); atribuição possivelmente duvidosa.","fontes":[{"nome":"Wikisource","url":"https://pt.wikisource.org/wiki/Vai-me_gastando_Amor_e_um_pensamento"}]}}
});
